INSERT INTO sport (sport_id, name, slug, default_structure, description) VALUES (2, 'Football', 'football', 'team', NULL);
INSERT INTO governing_body (body_id, name, abbrev, type, country_scope, website, notes) VALUES (2, 'National Football League', 'NFL', 'professional_league', 'USA', NULL, NULL);
INSERT INTO rulebook_series (series_id, sport_id, body_id, name, level, gender, structure, competition_system, notes) VALUES (2, 2, 2, 'NFL Football', 'professional', 'men', 'team', 'unknown', NULL);
INSERT INTO rulebook_edition (edition_id, series_id, year_start, year_end, edition_label, publication_date, language, page_count, token_count, legacy_catalog_id, canonical_doc_id, notes) VALUES (216, 2, 2023, NULL, '2023', NULL, 'en', NULL, 52644, 216, 216, 'Rules 1-2 (The Field/The Ball) restored 2026-07-04 (audit F03); parser had dropped article-less top rules.');
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8642, 216, NULL, NULL, 1, 0, 'rule', '1', '1', 'THE FIELD', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8643, 216, 8642, NULL, 1, 1, 'section', '1', '1.1', 'DIMENSIONS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8644, 216, 8643, NULL, 1, 2, 'article', '1', '1.1.1', 'PLAYING LINES', 'The game shall be played upon a rectangular field, 360 feet in length and 160 feet in width. [truncated]', 781, 145);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8645, 216, 8643, NULL, 2, 2, 'article', '2', '1.1.2', 'FIELD', 'The field includes the field of play and the end zones. [truncated]', 1310, 228);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8646, 216, 8642, NULL, 2, 1, 'section', '2', '1.2', 'MARKINGS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8647, 216, 8646, NULL, 1, 2, 'article', '1', '1.2.1', 'LINE MARKINGS', 'At intervals of 5 yards, yard lines (3-12-9) parallel to the goal lines shall be marked in the field of play. [truncated]', 452, 85);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8648, 216, 8646, NULL, 2, 2, 'article', '2', '1.2.2', 'INBOUND LINES', 'In line with the inbound lines there shall be marks at 1-yard intervals between each distance of 5 yards for the full length of the field. [truncated]', 1253, 224);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8649, 216, 8646, NULL, 3, 2, 'article', '3', '1.2.3', 'GOAL LINE', 'All measurements are to be made from the inside edges of the line marking the boundary lines. [truncated]', 546, 108);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8650, 216, 8642, NULL, 3, 1, 'section', '3', '1.3', 'GOAL', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8651, 216, 8650, NULL, 1, 2, 'article', '1', '1.3.1', 'CROSSBAR', 'In the plane of each end line, there shall be a centrally placed horizontal crossbar 18 feet, 6 inches in length, the top face of which is 10 feet above the ground. [truncated]', 307, 56);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8652, 216, 8650, NULL, 2, 2, 'article', '2', '1.3.2', 'GOAL POSTS', 'All goal posts will be the single-standard type, offset from the end line and bright gold in color. [truncated]', 384, 74);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8653, 216, NULL, NULL, 3, 0, 'rule', '3', '3', 'DEFINITIONS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8654, 216, 8653, NULL, 1, 1, 'section', '2', '3.2', 'THE BALL AND POSSESSION OF THE BALL', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8655, 216, 8654, NULL, 1, 2, 'article', '1', '3.2.1', 'DEAD BALL', 'A dead ball is one that is not in play. [truncated]', 248, 46);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8656, 216, 8654, NULL, 2, 2, 'article', '2', '3.2.2', 'BALL READY FOR PLAY', 'A dead ball is ready for play while the 40-second play clock is running when the ball is placed down by an official at the spot where the ball will next be put in play, or when the Referee signals for the 25-second play [truncated]', 235, 47);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8657, 216, 8654, NULL, 3, 2, 'article', '3', '3.2.3', 'LIVE BALL', 'A live ball is a ball that is in play. [truncated]', 292, 58);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8658, 216, 8654, NULL, 4, 2, 'article', '4', '3.2.4', 'LOOSE BALL', 'A loose ball is a live ball that is not in player possession, i.e., any ball that has been kicked, passed, or fumbled. [truncated]', 380, 73);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8659, 216, 8654, NULL, 5, 2, 'article', '5', '3.2.5', 'FUMBLE', 'A fumble is any act, other than passing, successful handing, or legally kicking the ball, which results in a loss of player possession. [truncated]', 531, 98);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8660, 216, 8654, NULL, 6, 2, 'article', '6', '3.2.6', 'MUFF', 'A muff is the touching of a loose ball by a player in an unsuccessful attempt to obtain possession of it. [truncated]', 1027, 189);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8661, 216, 8654, NULL, 7, 2, 'article', '7', '3.2.7', 'PLAYER POSSESSION', 'A player is in possession when he is inbounds and has control of the ball with his hands or arms. [truncated]', 2899, 524);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8662, 216, 8653, NULL, 2, 1, 'section', '9', '3.9', 'DOWN', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8663, 216, 8662, NULL, 1, 2, 'article', '1', '3.9.1', 'DOWN', 'A down is a period of action that starts when the ball is put in play (3-2-3) and ends when the ball is declared dead (7-2-1). [truncated]', 338, 69);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8664, 216, 8662, NULL, 2, 2, 'article', '2', '3.9.2', 'SERIES OF DOWNS', 'A series of downs is the four consecutive charged scrimmage downs allotted to the offensive team during which it must advance the ball to a yard line called "the line to gain" in order to retain possession.', 206, 37);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8665, 216, 8662, NULL, 3, 2, 'article', '3', '3.9.3', 'LINE TO GAIN', 'The line to gain is the spot 10 yards in advance of the spot of the snap that starts a series, except when a goal line is less than 10 yards from this spot. [truncated]', 205, 45);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8666, 216, 8662, NULL, 4, 2, 'article', '4', '3.9.4', 'CHARGED DOWN', 'A charged down is a scrimmage down that is not nullified by a penalty, or during which there is not a change of possession. [truncated]', 165, 34);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8667, 216, 8662, NULL, 5, 2, 'article', '5', '3.9.5', 'FIRST DOWN', 'The initial down in each series is the first down. [truncated]', 229, 40);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8668, 216, 8653, NULL, 3, 1, 'section', '12', '3.12', 'THE FIELD', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8669, 216, 8668, NULL, 1, 2, 'article', '1', '3.12.1', 'BOUNDARY LINES', 'The boundary lines are the end lines and the sidelines and enclose the field upon which the game is played.', 107, 20);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8670, 216, 8668, NULL, 2, 2, 'article', '2', '3.12.2', 'END LINES', 'The end lines are the lines at each end of the field and are perpendicular to the sidelines. [truncated]', 169, 36);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8671, 216, 8668, NULL, 3, 2, 'article', '3', '3.12.3', 'END ZONE', 'The end zone is the rectangle formed by the goal line, the end line, and the sidelines. [truncated]', 137, 28);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8672, 216, 8668, NULL, 4, 2, 'article', '4', '3.12.4', 'FIELD OF PLAY', 'The field of play is the rectangle formed by the goal lines and the sidelines. [truncated]', 112, 22);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8673, 216, 8668, NULL, 5, 2, 'article', '5', '3.12.5', 'GOAL', 'The goal is the area above the crossbar between the uprights, or, if above the uprights, the area between the outside edges of the uprights. [truncated]', 236, 45);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8674, 216, 8668, NULL, 6, 2, 'article', '6', '3.12.6', 'GOAL LINES', 'The goal lines are the lines between the sidelines that separate the end zone from the field of play. [truncated]', 190, 36);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8675, 216, 8668, NULL, 7, 2, 'article', '7', '3.12.7', 'INBOUNDS LINES', 'The inbounds lines are hash marks on the field of play that are 70 feet nine inches from and parallel to each sideline.', 119, 23);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8676, 216, 8668, NULL, 8, 2, 'article', '8', '3.12.8', 'SIDELINES', 'The sidelines are the lines on each side of the field and are perpendicular to the end lines. [truncated]', 171, 33);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8677, 216, 8668, NULL, 9, 2, 'article', '9', '3.12.9', 'YARD LINE', 'A yard line is any line and its vertical plane parallel to the end line. [truncated]', 433, 89);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8678, 216, 8653, NULL, 4, 1, 'section', '13', '3.13', 'FORWARD PROGRESS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8679, 216, 8678, NULL, 1, 2, 'article', '1', '3.13.1', 'FORWARD PROGRESS', 'The forward progress of a runner or airborne receiver is the point at which his advance toward his opponent''s goal ends and is the spot at which the ball is declared dead by rule, irrespective of the runner or receiver [truncated]', 267, 48);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8680, 216, 8678, NULL, 2, 2, 'article', '2', '3.13.2', 'FORWARD, BEYOND, OR IN ADVANCE', 'Forward, beyond, or in advance of are terms that designate a point nearer the goal line of the defense. [truncated]', 291, 53);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8681, 216, 8653, NULL, 5, 1, 'section', '14', '3.14', 'FOULS AND SPOTS OF ENFORCEMENT, VIOLATION', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8682, 216, 8681, NULL, 1, 2, 'article', '1', '3.14.1', 'TYPES OF FOULS', 'A foul is any infraction of a playing rule for which a penalty is prescribed. [truncated]', 743, 148);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8683, 216, 8681, NULL, 2, 2, 'article', '2', '3.14.2', 'BASIC SPOT', 'The basic spot is a reference point for specific types of plays that is used to determine the spot of enforcement.', 114, 21);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8684, 216, 8681, NULL, 3, 2, 'article', '3', '3.14.3', 'SPOTS OF ENFORCEMENT', 'The spot of enforcement is the spot at which a penalty is enforced. [truncated]', 945, 184);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8685, 216, 8681, NULL, 4, 2, 'article', '4', '3.14.4', 'VIOLATION', 'A violation is an infraction of a playing rule for which a penalty is not prescribed. [truncated]', 121, 23);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8686, 216, 8653, NULL, 6, 1, 'section', '18', '3.18', 'KICKS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8687, 216, 8686, NULL, 1, 2, 'article', '1', '3.18.1', 'KICK', 'A kick is intentionally striking the ball with the knee, lower leg, or foot. [truncated]', 641, 131);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8688, 216, 8686, NULL, 2, 2, 'article', '2', '3.18.2', 'KICKER', 'A kicker is the player of Team A who legally drop kicks, placekicks, or punts the ball. [truncated]', 204, 40);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8689, 216, 8686, NULL, 3, 2, 'article', '3', '3.18.3', 'RECEIVER', 'A receiver is any Team B player during a down in which there is a scrimmage kick, free kick, or fair catch kick. [truncated]', 179, 35);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8690, 216, 8686, NULL, 4, 2, 'article', '4', '3.18.4', 'FAIR CATCH KICK', 'A fair catch kick is a drop kick or placekick without a tee from the spot of a fair catch in an attempt to score a field goal.', 126, 28);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8691, 216, 8686, NULL, 5, 2, 'article', '5', '3.18.5', 'FREE KICK', 'A free kick is a kickoff or safety kick that puts the ball in play to start a free kick down. [truncated]', 349, 74);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8692, 216, 8686, NULL, 6, 2, 'article', '6', '3.18.6', 'RESTRAINING LINES', 'The restraining lines are lines which restrict the alignment of the kicking and receiving teams during a free kick and fair catch kick.', 135, 23);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8693, 216, 8686, NULL, 7, 2, 'article', '7', '3.18.7', 'SCRIMMAGE KICK', 'A scrimmage kick is a punt, drop kick, or placekick from on or behind the line of scrimmage.', 92, 18);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8694, 216, 8686, NULL, 8, 2, 'article', '8', '3.18.8', 'TEE', 'A tee is an approved device that is used to elevate the ball for a placekick during a kickoff.', 94, 19);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8695, 216, 8653, NULL, 7, 1, 'section', '19', '3.19', 'LINE OF SCRIMMAGE, NEUTRAL ZONE', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8696, 216, 8695, NULL, 1, 2, 'article', '1', '3.19.1', 'SCRIMMAGE LINE', 'The line of scrimmage is the vertical plane of the yard line that passes through the forward point of the ball after it has been made ready for play. [truncated]', 214, 40);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8697, 216, 8695, NULL, 2, 2, 'article', '2', '3.19.2', 'NEUTRAL ZONE', 'The neutral zone is the space between the forward and backward points of the ball (planes) and extends to the sidelines. [truncated]', 200, 35);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8698, 216, 8695, NULL, 3, 2, 'article', '3', '3.19.3', 'PLAYER ON LINE OF SCRIMMAGE', 'A player of Team A, who is on the line of scrimmage, must have his shoulders facing Team B''s goal line. [truncated]', 749, 150);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8699, 216, 8695, NULL, 4, 2, 'article', '4', '3.19.4', 'ENCROACHING', 'A player is encroaching (7-4-3) on the neutral zone when any part of his body is in it and he contacts an offensive player or the ball prior to the snap.', 153, 31);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8700, 216, 8695, NULL, 5, 2, 'article', '5', '3.19.5', NULL, 'LOOSE BALL CROSSES LINE OF SCRIMMAGE A loose ball has crossed the line of scrimmage when, as the result of a fumble, pass, or legal kick by a Team A player, it touches the ground or any player or official beyond the [truncated]', 229, 44);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8701, 216, 8653, NULL, 8, 1, 'section', '21', '3.21', 'OUT OF BOUNDS, INBOUNDS, AND INBOUNDS SPOT', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8702, 216, 8701, NULL, 1, 2, 'article', '1', '3.21.1', 'PLAYER OR OFFICIAL OUT OF BOUNDS', 'A player or an official is out of bounds when he touches a boundary line, or when he touches anything that is on or outside a boundary line, except a player, an official, or a pylon.', 182, 36);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8703, 216, 8701, NULL, 2, 2, 'article', '2', '3.21.2', 'PLAYER INBOUNDS', 'A player who has been out of bounds re-establishes himself as an inbounds player when both feet, or any part of his body other than his hands, touch the ground within the boundary lines, provided that no part of his [truncated]', 336, 63);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8704, 216, 8701, NULL, 3, 2, 'article', '3', '3.21.3', 'BALL OUT OF BOUNDS', 'Item 1. [truncated]', 447, 87);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8705, 216, 8701, NULL, 4, 2, 'article', '4', '3.21.4', 'OUT OF BOUNDS SPOT', 'Item 1. [truncated]', 765, 148);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8706, 216, 8701, NULL, 5, 2, 'article', '5', '3.21.5', 'INBOUNDS SPOT', 'The inbounds spot is a spot on the Inbounds Line (the hash marks) that passes through the spot where the ball went out of bounds between the goal lines.', 152, 29);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8707, 216, 8653, NULL, 9, 1, 'section', '22', '3.22', 'PASS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8708, 216, 8707, NULL, 1, 2, 'article', '1', '3.22.1', 'PASS', 'A pass is the movement caused by a player intentionally handing, throwing, shoveling (shovel pass), or pushing (push pass) the ball (3-25-2). [truncated]', 268, 46);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8709, 216, 8707, NULL, 2, 2, 'article', '2', '3.22.2', 'PASSER AND PASSING TEAM', 'A player who makes a legal forward pass is known as the passer until the play ends. [truncated]', 217, 39);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8710, 216, 8707, NULL, 3, 2, 'article', '3', '3.22.3', 'PASS PLAY', 'A pass play begins with the snap and ends when a forward pass thrown from behind the line of scrimmage is caught by a player of either team or is incomplete. [truncated]', 206, 40);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8711, 216, 8707, NULL, 4, 2, 'article', '4', '3.22.4', 'FORWARD PASS', 'It is a forward pass if: (a) the ball initially moves forward (to a point nearer the opponent''s goal line) after leaving the passer''s hand(s); (b) the ball first touches the ground, a player, an official, or anything [truncated]', 1586, 286);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8712, 216, 8707, NULL, 5, 2, 'article', '5', '3.22.5', 'BACKWARD PASS', 'It is a backward pass if the yard line at which the ball is first touched by a player or the ground is parallel to or behind the yard line at which the ball leaves the passer''s hand. [truncated]', 400, 77);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8713, 216, 8653, NULL, 10, 1, 'section', '23', '3.23', 'PENALTY', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8714, 216, 8713, NULL, 1, 2, 'article', '1', '3.23.1', 'PENALTY', 'A penalty is imposed upon a team that has committed a foul and may result in loss of down, loss of yardage, an automatic first down, a charged timeout, a loss of playing time, withdrawal or disqualification of a player, [truncated]', 299, 55);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8715, 216, 8713, NULL, 2, 2, 'article', '2', '3.23.2', 'LOSS OF DOWN', 'The phrase loss of down indicates that a team committing a foul will not have the opportunity to repeat the down after enforcement of any yardage penalty.', 154, 27);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8716, 216, 8653, NULL, 11, 1, 'section', '25', '3.25', 'PLAYS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8717, 216, 8716, NULL, 1, 2, 'article', '1', '3.25.1', 'FREE KICK PLAY', 'A free kick play begins with a legal or illegal free kick and ends when a player of either team establishes possession of the ball, or when the ball is dead by rule. [truncated]', 235, 45);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8718, 216, 8716, NULL, 2, 2, 'article', '2', '3.25.2', 'PASSING PLAY', 'A pass play begins with the snap and ends when a forward pass thrown from behind the line of scrimmage is caught by a player of either team or is incomplete. [truncated]', 1700, 318);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8719, 216, 8716, NULL, 3, 2, 'article', '4', '3.25.4', 'SCRIMMAGE KICK PLAY', 'A scrimmage kick play begins with the snap. [truncated]', 155, 30);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8720, 216, 8716, NULL, 4, 2, 'article', '5', '3.25.5', 'FAIR CATCH KICK PLAY', 'A fair catch kick play begins when the ball is kicked. [truncated]', 161, 32);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8721, 216, 8716, NULL, 5, 2, 'article', '6', '3.25.6', 'COMBINATIONS OF PLAYS', 'There may be a combination of a running play and a passing play, free kick play, scrimmage kick play, or fair catch kick play during the same down, and there may be more than one running play or scrimmage kick play [truncated]', 236, 45);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8722, 216, 8653, NULL, 12, 1, 'section', '36', '3.36', 'TEAM A AND B, OFFENSE AND DEFENSE', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8723, 216, 8722, NULL, 1, 2, 'article', '1', '3.36.1', 'OFFENSE AND DEFENSE', 'Whenever a team is in possession (3-2-7) of the ball, it is the offense, and its opponent is the defense. [truncated]', 225, 42);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8724, 216, 8722, NULL, 2, 2, 'article', '2', '3.36.2', 'TEAM A AND TEAM B', 'The team that puts the ball in play is Team A, and its opponent is Team B. [truncated]', 423, 87);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8725, 216, 8722, NULL, 3, 2, 'article', '3', '3.36.3', 'CHANGE OF POSSESSION', 'A change of possession occurs when a player of the defensive team secures possession of a ball that has been kicked, passed, or fumbled by a player of the offensive team, or when the ball is awarded to the opposing team [truncated]', 589, 112);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8726, 216, 8653, NULL, 13, 1, 'section', '37', '3.37', 'TIMEOUT OR TIME IN', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8727, 216, 8726, NULL, 1, 2, 'article', '1', '3.37.1', 'TIMEOUT', 'A timeout is any interval during which the game clock is stopped (4-4) and includes the intermission (4- 1-2 and 4-1-3). [truncated]', 591, 99);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8728, 216, 8726, NULL, 2, 2, 'article', '2', '3.37.2', 'CHARGED TEAM TIMEOUT', 'A charged team timeout is an interval during which the game clock is stopped and play is suspended at the request of one of the teams or when it is charged to one of the teams by rule. [truncated]', 237, 49);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8729, 216, 8726, NULL, 3, 2, 'article', '3', '3.37.3', 'TIME IN', 'Time In is any interval during which the game clock is running (4-3).', 69, 13);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8730, 216, NULL, NULL, 4, 0, 'rule', '4', '4', 'GAME TIMING', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8731, 216, 8730, NULL, 1, 1, 'section', '1', '4.1', 'PERIODS, INTERMISSIONS, HALFTIME', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8732, 216, 8731, NULL, 1, 2, 'article', '1', '4.1.1', 'LENGTH OF GAME', 'The length of the game is 60 minutes, divided into four periods of 15 minutes each. [truncated]', 224, 44);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8733, 216, 8731, NULL, 2, 2, 'article', '2', '4.1.2', 'INTERMISSIONS', 'There will be intervals of at least two minutes between the first and second periods (first half) and between the third and fourth periods (second half). [truncated]', 915, 155);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8734, 216, 8731, NULL, 3, 2, 'article', '3', '4.1.3', 'HALFTIME', 'Between the second and third periods, there shall be an intermission of 13 minutes. [truncated]', 245, 40);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8735, 216, 8731, NULL, 4, 2, 'article', '4', '4.1.4', 'OFFICIAL TIME', 'The stadium electric clock shall be the official time. [truncated]', 497, 88);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8736, 216, 8730, NULL, 2, 1, 'section', '2', '4.2', 'STARTING A PERIOD OR HALF', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8737, 216, 8736, NULL, 1, 2, 'article', '1', '4.2.1', 'KICKOFF ON SCHEDULE', 'Both teams must be on the field to kick off at the scheduled time for the start of each half. [truncated]', 778, 146);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8738, 216, 8736, NULL, 2, 2, 'article', '2', '4.2.2', 'TOSS OF COIN', 'Not more than three minutes before the kickoff of the first half, the Referee, in the presence of both team''s captains (limit of six per team, active, inactive or honorary) shall toss a coin at the center of the field. [truncated]', 1549, 290);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8739, 216, 8736, NULL, 3, 2, 'article', '3', '4.2.3', 'CHANGE OF GOALS', 'At the end of the first and third periods, the teams must change goals. [truncated]', 217, 41);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8740, 216, 8730, NULL, 3, 1, 'section', '3', '4.3', 'STARTING THE GAME CLOCK', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8741, 216, 8740, NULL, 1, 2, 'article', '1', '4.3.1', 'FREE KICK DOWN', 'The game clock operator shall start the game clock (time in) after a free kick when the ball is legally touched in the field of play. [truncated]', 447, 87);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8742, 216, 8740, NULL, 2, 2, 'article', '2', '4.3.2', 'SCRIMMAGE DOWN', 'Following any timeout (3-37-1), the game clock shall be started on a scrimmage down when the ball is next snapped, except in the following situations: (a) Whenever a runner goes out of bounds on a play from scrimmage, [truncated]', 1997, 368);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8743, 216, 8740, NULL, 3, 2, 'article', '3', '4.3.3', 'FAIR CATCH KICK DOWN', 'The game clock operator shall start the game clock for a fair catch kick down when the ball is kicked.', 102, 20);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8744, 216, 8730, NULL, 4, 1, 'section', '5', '4.5', 'TIMEOUTS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8745, 216, 8744, NULL, 1, 2, 'article', '1', '4.5.1', 'CHARGED TEAM TIMEOUTS', 'The Referee shall suspend play while the ball is dead and declare a charged team timeout upon the request for a timeout by the head coach or any player (not a substitute) to any official. [truncated]', 2090, 368);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8746, 216, 8744, NULL, 2, 2, 'article', '2', '4.5.2', 'INJURY TIMEOUTS', 'If an official determines a player to be injured, or if attendants from the bench come on the field to assist an injured player, an injury timeout will be called by the Referee. [truncated]', 317, 57);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8747, 216, 8744, NULL, 3, 2, 'article', '3', '4.5.3', 'INJURY TIMEOUTS PRIOR TO TWO-MINUTE WARNING OF EITHER HALF', 'When an injury timeout is called, the injured player must leave the game for the completion of one down. [truncated]', 534, 101);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8748, 216, 8744, NULL, 4, 2, 'article', '4', '4.5.4', 'INJURY TIMEOUTS AFTER TWO-MINUTE WARNING OF EITHER HALF', 'After the two-minute warning of a half, the following shall apply: (a) If a team has not used its three charged team timeouts, the team of the injured player will be charged a team timeout, unless: (1) the injury is the [truncated]', 2969, 542);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8749, 216, 8744, NULL, 5, 2, 'article', '5', '4.5.5', 'REFEREE''S TIMEOUT', 'Provided that calling timeout is not in conflict with another rule, the Referee may suspend play and stop the clock (Referee''s timeout) at any time without penalty to either team when playing time is being consumed [truncated]', 1113, 199);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8750, 216, 8730, NULL, 5, 1, 'section', '6', '4.6', 'DELAY OF GAME', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8751, 216, 8750, NULL, 1, 2, 'article', '1', '4.6.1', '40-SECOND PLAY CLOCK', 'It is a delay of the game if the ball is not put in play by a snap within 40 seconds after the start of the play clock. [truncated]', 295, 56);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8752, 216, 8750, NULL, 2, 2, 'article', '2', '4.6.2', '25-SECOND PLAY CLOCK', 'In the event of certain administrative stoppages or other delays, a team will have 25 seconds, beginning with the Referee''s whistle, to put the ball in play next by a snap or a kick. [truncated]', 812, 143);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8753, 216, 8750, NULL, 3, 2, 'article', '3', '4.6.3', 'INTERRUPTION OF PLAY CLOCK', 'If the play clock is stopped prior to the snap for any reason, after the stoppage has concluded, the time remaining on the play clock shall be the same as when it stopped, unless: (a) the stoppage has been for a charged [truncated]', 880, 166);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8754, 216, 8750, NULL, 4, 2, 'article', '4', '4.6.4', 'BALL REMAINS DEAD', 'If the ball is not put in play within the applicable period, the Back Judge shall blow his whistle for the foul, and the ball remains dead. [truncated]', 158, 30);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8755, 216, 8750, NULL, 5, 2, 'article', '5', '4.6.5', 'OTHER DELAY OF GAME FOULS', 'Other examples of action or inaction that are to be construed as delay of the game include, but are not limited to: (a) a player unnecessarily remains on a dead ball or on a runner who has been downed; (b) the snapper [truncated]', 1421, 258);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8756, 216, 8730, NULL, 6, 1, 'section', '7', '4.7', 'ACTIONS TO CONSERVE TIME', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8757, 216, 8756, NULL, 1, 2, 'article', '1', '4.7.1', 'ILLEGAL ACTS', 'A team is not permitted to conserve time after the two-minute warning of either half by committing any of these acts: (a) a foul by either team that prevents the snap (i.e., false start, encroachment, etc.); (b) [truncated]', 1578, 282);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8758, 216, 8756, NULL, 2, 2, 'article', '2', '4.7.2', 'SUBSTITUTION VIOLATION AFTER TWO-MINUTE WARNING', 'After the two-minute warning of either half, if there is a violation of the substitution rule while the ball is dead and time is in, in addition to the applicable yardage penalty for illegal substitution, there will be [truncated]', 474, 79);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8759, 216, 8756, NULL, 3, 2, 'article', '3', '4.7.3', 'DEFENSIVE FOULS DURING LAST 40 SECONDS', 'In the last 40 seconds of either half, if there is a defensive foul prior to the snap while time is in, the half will end, unless the defense has timeouts remaining, or the offense chooses to have the game clock start [truncated]', 230, 45);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8760, 216, 8756, NULL, 4, 2, 'article', '4', '4.7.4', 'REPLAY REVIEW AFTER TWO-MINUTE WARNING OF EITHER HALF', 'If a replay review after the two-minute warning of either half results in the on-field ruling being reversed and the correct ruling would not have stopped the game clock, or would have otherwise restarted the game clock [truncated]', 504, 91);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8761, 216, 8730, NULL, 7, 1, 'section', '8', '4.8', 'EXTENSION OF A PERIOD OR A HALF', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8762, 216, 8761, NULL, 1, 2, 'article', '1', '4.8.1', 'BALL IN PLAY', 'If time expires at the end of any period while the ball is in play, the period continues until the down ends.', 109, 22);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8763, 216, 8761, NULL, 2, 2, 'article', '2', '4.8.2', 'PERIOD EXTENDED', 'A period may be extended for one untimed down, if any of the following occurs during a down during which time in the period expires, or during which the period had been extended pursuant to this Article: (a) If there is [truncated]', 3422, 646);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8764, 216, NULL, NULL, 5, 0, 'rule', '5', '5', 'PLAYERS, SUBSTITUTES, EQUIPMENT, GENERAL RULES', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8765, 216, 8764, NULL, 1, 1, 'section', '1', '5.1', 'PLAYERS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8766, 216, 8765, NULL, 1, 2, 'article', '1', '5.1.1', 'NUMBER OF PLAYERS', 'The game is played by two teams of 11 players each. [truncated]', 909, 187);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8767, 216, 8765, NULL, 2, 2, 'article', '2', '5.1.2', 'PLAYERS NUMBERED BY POSITION', 'All players must wear numerals on their jerseys in accordance with Rule 5, Section 4, Article 3, Item 3. [truncated]', 1625, 269);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8768, 216, 8764, NULL, 2, 1, 'section', '2', '5.2', 'SUBSTITUTES AND WITHDRAWN PLAYERS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8769, 216, 8768, NULL, 1, 2, 'article', '1', '5.2.1', 'NUMBER OF PLAYERS IN HUDDLE', 'There can never be more than 11 players in the offensive huddle while the play clock is running. [truncated]', 184, 34);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8770, 216, 8768, NULL, 2, 2, 'article', '2', '5.2.2', 'SUBSTITUTE BECOMES PLAYER', 'A substitute becomes a player when he: (a) participates in at least one play (including a play negated by penalty prior to the snap or during the play); or (b) is on the field of play or the end zone when a snap, fair [truncated]', 510, 102);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8771, 216, 8768, NULL, 3, 2, 'article', '3', '5.2.3', 'LEGAL SUBSTITUTIONS', 'Any number of substitutes may enter the field of play or the end zone while the ball is dead.', 93, 19);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8772, 216, 8768, NULL, 4, 2, 'article', '4', '5.2.4', 'ILLEGAL SUBSTITUTIONS', 'If a substitute enters the field of play or the end zone while the ball is in play, it is an illegal substitution. [truncated]', 1611, 286);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8773, 216, 8768, NULL, 5, 2, 'article', '6', '5.2.6', 'WITHDRAWN PLAYERS', 'A player or players who have been replaced must leave the playing field or end zone on their own team''s side between the end lines prior to the next snap, free kick, or fair catch kick.', 185, 36);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8774, 216, 8768, NULL, 6, 2, 'article', '7', '5.2.7', 'DISQUALIFIED AND SUSPENDED PLAYERS', 'A player must be withdrawn and substituted for when he is disqualified (12-2, 12-3) or suspended (5-4). [truncated]', 348, 58);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8775, 216, 8768, NULL, 7, 2, 'article', '8', '5.2.8', 'PENALTIES FOR ILLEGAL SUBSTITUTION OR WITHDRAWAL', 'Penalties are: (a) For 12 or more players in the offensive huddle (whistle blown immediately and ball remains dead): Loss of five yards from the succeeding spot. [truncated]', 1389, 250);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8776, 216, 8768, NULL, 8, 2, 'article', '9', '5.2.9', 'PROCEDURE FOLLOWING TIMEOUT OR CHANGE OF POSSESSION', 'Following a timeout or change of possession, the offense may huddle outside the numbers near its bench area, but will not be allowed to line up and snap the ball before the defense has an opportunity to match personnel. [truncated]', 749, 127);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8777, 216, 8768, NULL, 9, 2, 'article', '10', '5.2.10', 'DEFENSIVE MATCHUPS FOLLOWING SUBSTITUTIONS', 'If a substitution is made by the offense before the two- minute warning of either half, the offense shall not be permitted to snap the ball until the defense has been permitted to respond with its substitutions. [truncated]', 1542, 264);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8778, 216, 8768, NULL, 10, 2, 'article', '11', '5.2.11', 'UNSPORTSMANLIKE CONDUCT', 'Using entering substitutes, legally returning players, substitutes on sidelines, or withdrawn players to confuse opponents, or lingering by players leaving the field when being replaced by a substitute, is [truncated]', 504, 72);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8779, 216, 8764, NULL, 3, 1, 'section', '3', '5.3', 'CHANGES IN POSITION', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8780, 216, 8779, NULL, 1, 2, 'article', '1', '5.3.1', 'REPORTING CHANGE OF POSITION', 'An offensive player wearing the number of an ineligible pass receiver (50- 79 and 90-99) is permitted to line up in the position of an eligible pass receiver (0-49 and 80-89). [truncated]', 957, 168);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8781, 216, 8779, NULL, 2, 2, 'article', '2', '5.3.2', 'RETURNING TO ORIGINAL POSITION', 'A player who has reported a change in his eligibility status to the Referee is permitted to return to a position indicated by the eligibility status of his number after: (a) a team time out; (b) the end of a quarter; [truncated]', 659, 118);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8782, 216, 8779, NULL, 3, 2, 'article', '3', '5.3.3', 'SPEAKERS IN HELMETS', 'The Coach-to-Player system allows a member of the coaching staff in the bench area or the coaches'' booth to communicate to a designated offensive or defensive player with a speaker in his helmet. [truncated]', 2622, 458);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8783, 216, 8764, NULL, 4, 1, 'section', '4', '5.4', 'EQUIPMENT, UNIFORMS, PLAYER APPEARANCE', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8784, 216, 8783, NULL, 1, 2, 'article', '1', '5.4.1', 'GENERAL POLICY', 'Throughout the game day period while in view of the stadium and television audience, including during team pregame warm-ups, all players must dress in a professional manner under the uniform standards. [truncated]', 1183, 189);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8785, 216, 8783, NULL, 2, 2, 'article', '2', '5.4.2', 'TEAM COLORS', 'Pursuant to the official colors established for each NFL club in the League Constitution and Bylaws, playing squads are permitted to wear only those colors or a combination of those colors for helmets, jerseys, pants, [truncated]', 911, 148);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8786, 216, 8783, NULL, 3, 2, 'article', '3', '5.4.3', 'MANDATORY EQUIPMENT, APPAREL', 'All players must wear the equipment and uniform apparel listed below, which must be of a suitably protective nature and must be designed and produced by a professional football equipment manufacturer. [truncated]', 6746, 1162);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8787, 216, 8783, NULL, 4, 2, 'article', '4', '5.4.4', 'OTHER PROHIBITED EQUIPMENT, APPAREL', 'In addition to the prohibited items of equipment and apparel specified above, the following also are prohibited: Item 1. [truncated]', 2736, 457);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8788, 216, 8783, NULL, 5, 2, 'article', '5', '5.4.5', 'RECOMMENDED EQUIPMENT', 'It is recommended that all players wear hip pads designed to reasonably avoid the risk of injury. [truncated]', 311, 51);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8789, 216, 8783, NULL, 6, 2, 'article', '6', '5.4.6', 'OPTIONAL EQUIPMENT', 'Among the types of optional equipment that are permitted to be worn by players are the following: Item 1. [truncated]', 3512, 592);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8790, 216, 8783, NULL, 7, 2, 'article', '7', '5.4.7', 'LOGOS AND COMMERCIAL IDENTIFICATION', 'Throughout the period on game day that a player is visible to the stadium and television audience (including in pregame warm-ups, in the bench area, and during postgame interviews in the locker room or on the field), [truncated]', 714, 111);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8791, 216, 8783, NULL, 8, 2, 'article', '8', '5.4.8', 'PERSONAL MESSAGES', 'Throughout the period on game day that a player is visible to the stadium and television audience (including in pregame warm-ups, in the bench area, and during postgame interviews in the locker room or on the field), [truncated]', 1370, 218);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8792, 216, 8783, NULL, 9, 2, 'article', '9', '5.4.9', 'GENERAL APPEARANCE', 'Consistent with the equipment and uniform rules, players must otherwise present a professional and appropriate appearance while before the public on game day. [truncated]', 2549, 427);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8793, 216, NULL, NULL, 6, 0, 'rule', '6', '6', 'FREE KICKS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8794, 216, 8793, NULL, 1, 1, 'section', '1', '6.1', 'PROCEDURES FOR A FREE KICK', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8795, 216, 8794, NULL, 1, 2, 'article', '1', '6.1.1', 'FREE KICK', 'A free kick is a kickoff or safety kick that puts the ball in play to start a free kick down. [truncated]', 1336, 262);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8796, 216, 8794, NULL, 2, 2, 'article', '2', '6.1.2', 'RESTRAINING LINES', 'The restraining lines for a free kick shall be as follows, unless they are adjusted because of a distance penalty: (a) The restraining line for the kicking team shall be its 35-yard line for a kickoff and its 20-yard [truncated]', 371, 67);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8797, 216, 8794, NULL, 3, 2, 'article', '3', '6.1.3', 'FREE KICK FORMATION', 'When the ball is kicked on a free kick down: (a) From the time the kicker begins his approach to the ball and until the ball is kicked, (1) all kicking team players other than the kicker must be lined up with at least [truncated]', 1913, 357);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8798, 216, 8794, NULL, 4, 2, 'article', '4', '6.1.4', 'CATCH OR RECOVERY OF A FREE KICK', 'The following applies to the catch or recovery of a free kick: (a) If a player of the receiving team catches or recovers the ball, he may advance. [truncated]', 1197, 228);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8799, 216, 8794, NULL, 5, 2, 'article', '5', '6.1.5', 'FREE KICK CROSSES GOAL LINE', 'It is a touchback and the dead ball spot is the 25-yard line if a free kick: (a) touches the ground in the end zone before being touched by the receiving team; (b) goes out of bounds behind the receiving team''s goal [truncated]', 345, 66);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8800, 216, 8794, NULL, 6, 2, 'article', '6', '6.1.6', 'END OF FREE KICK', 'A free kick ends when either team possesses the ball, or when the ball is dead, if that precedes possession. [truncated]', 190, 33);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8801, 216, 8793, NULL, 2, 1, 'section', '2', '6.2', 'OTHER FREE KICK FOULS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8802, 216, 8801, NULL, 1, 2, 'article', '1', '6.2.1', 'BLOCKING', 'Item 1. [truncated]', 3370, 605);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8803, 216, 8801, NULL, 2, 2, 'article', '2', '6.2.2', 'RUNNING INTO FREE KICKER', 'A player of the receiving team is not permitted to run into the kicker before he recovers his balance. [truncated]', 217, 38);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8804, 216, 8801, NULL, 3, 2, 'article', '3', '6.2.3', 'FREE KICK OUT OF BOUNDS', 'The kicking team may not kick the ball out of bounds or be the last to touch the ball before it goes out of bounds between the goal lines. [truncated]', 775, 159);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8805, 216, 8801, NULL, 4, 2, 'article', '4', '6.2.4', 'FREE KICK ILLEGALLY TOUCHED', 'Item 1. [truncated]', 916, 165);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8806, 216, 8793, NULL, 3, 1, 'section', '3', '6.3', 'ENFORCEMENT OF FOULS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8807, 216, 8806, NULL, 1, 2, 'article', '1', '6.3.1', 'ENFORCEMENT FROM PREVIOUS SPOT', 'If there is a foul during a free kick, enforcement is from the previous spot, and the free kick is made again. [truncated]', 1471, 289);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8808, 216, NULL, NULL, 7, 0, 'rule', '7', '7', 'BALL IN PLAY, DEAD BALL, SCRIMMAGE', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8809, 216, 8808, NULL, 1, 1, 'section', '1', '7.1', 'BALL IN PLAY', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8810, 216, 8809, NULL, 1, 2, 'article', '1', '7.1.1', 'LIVE BALL', 'After the ball has been declared ready for play, it becomes a live ball when it is legally snapped or legally kicked (a free kick or fair catch kick). [truncated]', 233, 46);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8811, 216, 8808, NULL, 2, 1, 'section', '2', '7.2', 'DEAD BALL', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8812, 216, 8811, NULL, 1, 2, 'article', '1', '7.2.1', 'DEAD BALL DECLARED', 'An official shall declare the ball dead and the down ended: (a) when a runner is contacted by an opponent and touches the ground with any part of his body other than his hands (including the wrist) or feet (including [truncated]', 5017, 914);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8813, 216, 8811, NULL, 2, 2, 'article', '2', '7.2.2', 'BALL TOUCHES OFFICIAL', 'The ball is not dead because it touches an official who is inbounds, or because of a signal by an official other than a whistle.', 128, 25);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8814, 216, 8808, NULL, 3, 1, 'section', '3', '7.3', 'NEW SERIES OF DOWNS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8815, 216, 8814, NULL, 1, 2, 'article', '1', '7.3.1', 'NEW SERIES FOR TEAM A', 'A new series of four scrimmage downs is awarded to Team A when the following conditions exist: (a) During a given series, the ball is declared dead in possession of Team A while at or beyond the line to gain; (b) [truncated]', 702, 137);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8816, 216, 8814, NULL, 2, 2, 'article', '2', '7.3.2', 'NEW SERIES FOR TEAM B', 'A new series of four scrimmage downs is awarded to Team B when the following conditions exist: (a) Team A fails to advance the ball to the line to gain during a series of downs; (b) There is a change of possession [truncated]', 464, 91);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8817, 216, 8814, NULL, 3, 2, 'article', '3', '7.3.3', 'FORWARD PART OF BALL', 'The forward part of the ball in its position when it is declared dead in the field of play shall be the determining point in measuring any distance gained or lost. [truncated]', 610, 107);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8818, 216, 8808, NULL, 4, 1, 'section', '4', '7.4', 'ACTION AT OR BEFORE THE SNAP', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8819, 216, 8818, NULL, 1, 2, 'article', '1', '7.4.1', 'BALL READY FOR PLAY', 'After the neutral zone has been established (ball is made or declared ready for play), an offensive player may not make a false start, a defensive player may not encroach (initiate contact with a member of the offensive [truncated]', 336, 61);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8820, 216, 8818, NULL, 2, 2, 'article', '2', '7.4.2', 'FALSE START', 'It is a false start if the ball has been placed ready for play, and, prior to the snap, an offensive player who has assumed a set position moves in such a way as to simulate the start of a play, or if an offensive [truncated]', 3004, 560);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8821, 216, 8818, NULL, 3, 2, 'article', '3', '7.4.3', NULL, 'ENCROACHMENT It is encroachment if a defensive player enters the neutral zone and contacts an offensive player or the ball prior to the snap, or if he interferes with the ball during the snap. [truncated]', 359, 61);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8822, 216, 8818, NULL, 4, 2, 'article', '4', '7.4.4', 'NEUTRAL ZONE INFRACTION', 'It is a neutral zone infraction when the following occur. [truncated]', 1713, 292);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8823, 216, 8818, NULL, 5, 2, 'article', '5', '7.4.5', 'OFFSIDE', 'A player is offside when any part of his body is in or beyond the neutral zone or beyond a restraining line when the ball is put in play. [truncated]', 179, 36);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8824, 216, 8818, NULL, 6, 2, 'article', '6', '7.4.6', 'COMPLETE STOP', 'All offensive players are required to come to a complete stop and be in a set position simultaneously for at least one full second prior to the snap. [truncated]', 267, 50);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8825, 216, 8818, NULL, 7, 2, 'article', '7', '7.4.7', 'SHIFTS', 'The offensive team must present a legal formation before and after a shift. [truncated]', 957, 177);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8826, 216, 8818, NULL, 8, 2, 'article', '8', '7.4.8', 'ILLEGAL MOTION', 'When the ball is snapped, one player who is lined up in the backfield may be in motion, provided that he is moving parallel to or away from the line of scrimmage. [truncated]', 749, 144);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8827, 216, 8808, NULL, 5, 1, 'section', '5', '7.5', 'POSITION OF PLAYERS AT THE SNAP', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8828, 216, 8827, NULL, 1, 2, 'article', '1', '7.5.1', 'OFFENSIVE TEAM', 'The offensive team must be in compliance with the following at the snap: (a) It must have seven or more players on the line (3-19) (b) Eligible receivers must be on both ends of the line, and all of the players on the [truncated]', 405, 75);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8829, 216, 8808, NULL, 6, 1, 'section', '6', '7.6', 'PUTTING THE BALL IN PLAY', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8830, 216, 8829, NULL, 1, 2, 'article', '1', '7.6.1', 'BALL IN PLAY', 'The offensive team must put the ball in play with a snap at the spot where the previous down ended, unless the enforcement of a penalty moves the ball to another spot or the down ended outside the inbounds lines. [truncated]', 290, 55);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8831, 216, 8829, NULL, 2, 2, 'article', '2', '7.6.2', 'SNAP AT INBOUNDS SPOT', 'The ball is next put in play at the inbounds spot by the team entitled to possession (7- 1-1 and 7-4-1) when: (a) a loose ball other than an incomplete forward pass is out of bounds between the goal lines; (b) a runner [truncated]', 443, 91);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8832, 216, 8829, NULL, 3, 2, 'article', '3', '7.6.3', 'RESTRICTIONS FOR SNAPPER', 'The snap (3-32) may be made by any offensive player who is on the line of scrimmage but must conform to the following provisions: (a) The snap must start with the ball on the ground, with its long axis at right angles [truncated]', 819, 156);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8833, 216, 8829, NULL, 4, 2, 'article', '4', '7.6.4', 'LEGAL SNAP', 'A snap is a backward pass. [truncated]', 456, 83);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8834, 216, NULL, NULL, 8, 0, 'rule', '8', '8', 'FORWARD PASS, BACKWARD PASS, FUMBLE', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8835, 216, 8834, NULL, 1, 1, 'section', '1', '8.1', 'FORWARD PASS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8836, 216, 8835, NULL, 1, 2, 'article', '1', '8.1.1', 'DEFINITION', 'It is a forward pass if: (a) the ball initially moves forward (to a point nearer the opponent''s goal line) after leaving the passer''s hand(s); (b) the ball first strikes the ground, a player, an official, or anything [truncated]', 1379, 246);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8837, 216, 8835, NULL, 2, 2, 'article', '2', '8.1.2', 'LEGAL FORWARD PASS', 'The offensive team may make one forward pass from behind the line during each down. [truncated]', 2055, 365);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8838, 216, 8835, NULL, 3, 2, 'article', '3', '8.1.3', 'COMPLETED OR INTERCEPTED PASS', 'A player who makes a catch may advance the ball. [truncated]', 1947, 363);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8839, 216, 8835, NULL, 4, 2, 'article', '4', '8.1.4', 'INCOMPLETE PASS', 'An incomplete pass is a loss of down, and the ball returns to the previous spot. [truncated]', 601, 112);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8840, 216, 8835, NULL, 5, 2, 'article', '5', '8.1.5', 'ELIGIBLE RECEIVERS', 'The following players are eligible to catch a forward pass that is thrown from behind the line of scrimmage. [truncated]', 923, 160);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8841, 216, 8835, NULL, 6, 2, 'article', '6', '8.1.6', 'INELIGIBLE RECEIVERS', 'All offensive players other than those identified in Article 5 above are ineligible to catch a legal or illegal forward pass thrown from behind the line of scrimmage, including: (a) Players who are not on either end of [truncated]', 1148, 211);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8842, 216, 8835, NULL, 7, 2, 'article', '7', '8.1.7', 'LEGAL TOUCHING', 'A forward pass (legal or illegal) thrown from behind the line may be touched by any eligible player. [truncated]', 245, 46);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8843, 216, 8835, NULL, 8, 2, 'article', '8', '8.1.8', 'ILLEGAL TOUCHING OF A FORWARD PASS', 'It is a foul for illegal touching if a forward pass (legal or illegal) thrown from behind the line of scrimmage: (a) is first touched intentionally or is caught by an originally ineligible offensive player. [truncated]', 702, 129);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8844, 216, 8834, NULL, 2, 1, 'section', '2', '8.2', 'INTENTIONAL GROUNDING', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8845, 216, 8844, NULL, 1, 2, 'article', '1', '8.2.1', 'DEFINITION', 'It is a foul for intentional grounding if a passer, facing an imminent loss of yardage because of pressure from the defense, throws a forward pass without a realistic chance of completion. [truncated]', 2296, 406);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8846, 216, 8834, NULL, 3, 1, 'section', '3', '8.3', 'INELIGIBLE PLAYER DOWNFIELD', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8847, 216, 8846, NULL, 1, 2, 'article', '1', '8.3.1', 'LEGAL AND ILLEGAL ACTS', 'On a scrimmage play during which a legal forward pass is thrown, it is a foul if the entire body of an ineligible offensive player, including a T-Formation Quarterback, is more than one yard beyond the line of scrimmage [truncated]', 1778, 299);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8848, 216, 8846, NULL, 2, 2, 'article', '2', '8.3.2', 'AFTER PASS IS THROWN', 'After the ball leaves the passer''s hand, ineligible pass receivers can advance more than one yard beyond the line of scrimmage, or beyond the position reached by their initial charge, provided that they do not block or [truncated]', 549, 94);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8849, 216, 8834, NULL, 4, 1, 'section', '4', '8.4', 'LEGAL AND ILLEGAL CONTACT WITH ELIGIBLE RECEIVERS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8850, 216, 8849, NULL, 1, 2, 'article', '1', '8.4.1', 'LEGAL CONTACT WITHIN FIVE YARDS', 'Within the area five yards beyond the line of scrimmage, a defensive player may chuck an eligible receiver in front of him. [truncated]', 303, 53);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8851, 216, 8849, NULL, 2, 2, 'article', '2', '8.4.2', 'ILLEGAL CONTACT WITHIN FIVE YARDS', 'Within the five-yard zone, if the player who receives the snap remains in the pocket with the ball, a defender may not make initial contact in the back of a receiver, nor may he maintain contact after the receiver has [truncated]', 435, 78);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8852, 216, 8849, NULL, 3, 2, 'article', '3', '8.4.3', 'ILLEGAL CONTACT BEYOND FIVE-YARD ZONE', 'Beyond the five-yard zone, if the player who receives the snap remains in the pocket with the ball, a defender cannot initiate contact with a receiver who is attempting to evade him. [truncated]', 454, 79);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8853, 216, 8849, NULL, 4, 2, 'article', '4', '8.4.4', 'INCIDENTAL CONTACT BEYOND FIVE-YARD ZONE', 'Beyond the five-yard zone, incidental contact may exist between receiver and defender. [truncated]', 176, 27);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8854, 216, 8849, NULL, 5, 2, 'article', '5', '8.4.5', 'ILLEGAL CUT BLOCK', 'It is an illegal cut block if: (a) an eligible receiver who takes a position more than two yards outside of his own tackle (flexed receiver) is blocked below the waist at, behind, or beyond the line of scrimmage; or (b) [truncated]', 546, 101);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8855, 216, 8849, NULL, 6, 2, 'article', '6', '8.4.6', 'DEFENSIVE HOLDING', 'It is defensive holding if a player grasps an eligible offensive player (or his jersey) with his hands, or extends an arm or arms to cut off or encircle him. [truncated]', 411, 75);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8856, 216, 8849, NULL, 7, 2, 'article', '7', '8.4.7', 'END OF RESTRICTIONS', 'If the quarterback or the receiver of the snap demonstrates no further intention to pass the ball (i.e., hands off or pitches the ball to another player, throws a forward or backward pass, loses possession of the ball [truncated]', 997, 168);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8857, 216, 8834, NULL, 5, 1, 'section', '5', '8.5', 'PASS INTERFERENCE', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8858, 216, 8857, NULL, 1, 2, 'article', '1', '8.5.1', 'DEFINITION', 'It is pass interference by either team when any act by a player more than one yard beyond the line of scrimmage significantly hinders an eligible player''s opportunity to catch the ball. [truncated]', 1073, 192);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8859, 216, 8857, NULL, 2, 2, 'article', '2', '8.5.2', 'PROHIBITED ACTS BY BOTH TEAMS WHILE THE BALL IS IN THE AIR', 'Acts that are pass interference include, but are not limited to: (a) Contact by a player who is not playing the ball that restricts the opponent''s opportunity to make the catch; (b) Playing through the back of an [truncated]', 981, 175);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8860, 216, 8857, NULL, 3, 2, 'article', '3', '8.5.3', 'PERMISSIBLE ACTS BY BOTH TEAMS WHILE THE BALL IS IN THE AIR', 'Acts that are permissible by a player include, but are not limited to: (a) Incidental contact by an opponent''s hands, arms, or body when both players are competing for the ball, or neither player is looking for the ball. [truncated]', 1229, 214);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8861, 216, 8857, NULL, 4, 2, 'article', '4', '8.5.4', 'OTHER PROHIBITED ACTS BY THE OFFENSE', 'Acts that are pass interference include: (a) Blocking more than one yard beyond the line of scrimmage by an offensive player prior to a pass being thrown. [truncated]', 1085, 193);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8862, 216, 8834, NULL, 6, 1, 'section', '6', '8.6', 'ENFORCEMENT SPOT', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8863, 216, 8862, NULL, 1, 2, 'article', '1', '8.6.1', 'ENFORCEMENT SPOT', 'If there is a foul by either team from the time of the snap until a forward pass thrown from behind the line ends, the penalty is enforced from the previous spot. [truncated]', 1743, 312);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8864, 216, 8834, NULL, 7, 1, 'section', '7', '8.7', 'BACKWARD PASS AND FUMBLE', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8865, 216, 8864, NULL, 1, 2, 'article', '1', '8.7.1', 'BACKWARD PASS', 'A runner may throw a backward pass at any time (3-22-5). [truncated]', 272, 47);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8866, 216, 8864, NULL, 2, 2, 'article', '2', '8.7.2', 'BACKWARD PASS OUT OF BOUNDS', 'If a backward pass goes out of bounds between the goal lines, the ball is dead (7-6-2-a), and it is next put in play at the inbounds spot. [truncated]', 2316, 453);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8867, 216, 8864, NULL, 3, 2, 'article', '4', '8.7.4', 'HANDING BALL FORWARD', 'No player may hand the ball forward except to an eligible receiver who is behind the line of scrimmage. [truncated]', 684, 122);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8868, 216, 8864, NULL, 4, 2, 'article', '5', '8.7.5', 'FOURTH DOWN FUMBLE', 'If a fourth down fumble occurs during a play from scrimmage: (a) The ball may be advanced by any member of the defensive team. [truncated]', 528, 106);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8869, 216, 8864, NULL, 5, 2, 'article', '6', '8.7.6', 'FUMBLE AFTER TWO-MINUTE WARNING OR DURING A TRY', 'If a fumble by either team occurs after the two- minute warning or during a Try: (a) The ball may be advanced by any opponent. [truncated]', 472, 97);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8870, 216, 8864, NULL, 6, 2, 'article', '7', '8.7.7', 'ENFORCEMENT SPOT DURING A BACKWARD PASS OR FUMBLE', '(a) When the spot of the backward pass or fumble is beyond the line of scrimmage, or when there is not a line of scrimmage, and there is a foul during the backward pass or fumble, the basic spot is the spot of the [truncated]', 1067, 206);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8871, 216, NULL, NULL, 9, 0, 'rule', '9', '9', 'SCRIMMAGE KICK', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8872, 216, 8871, NULL, 1, 1, 'section', '1', '9.1', 'KICK FROM SCRIMMAGE', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8873, 216, 8872, NULL, 1, 2, 'article', '1', '9.1.1', NULL, 'KICK ON OR BEHIND LINE OF SCRIMMAGE Team A may attempt a punt, drop kick, or placekick from on or behind the line of scrimmage. [truncated]', 847, 159);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8874, 216, 8872, NULL, 2, 2, 'article', '2', '9.1.2', 'KICKING TEAM PLAYERS ON LINE DURING KICK', 'During a kick from scrimmage, only the end men (eligible receivers) on the line of scrimmage at the time of the snap, or an eligible receiver who is aligned or in motion behind the line and is more than one yard outside [truncated]', 407, 75);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8875, 216, 8872, NULL, 3, 2, 'article', '3', '9.1.3', 'DEFENSIVE TEAM FORMATION', 'Item 1. [truncated]', 1639, 301);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8876, 216, 8872, NULL, 4, 2, 'article', '4', '9.1.4', 'BLOCKING DURING KICK', 'The following blocking rules apply during a scrimmage kick down: (a) All players on the receiving team are prohibited from blocking below the waist during a down in which there is a scrimmage kick. [truncated]', 1908, 338);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8877, 216, 8872, NULL, 5, 2, 'article', '5', '9.1.5', 'KICKING TEAM PLAYER VOLUNTARILY OUT OF BOUNDS', 'During a scrimmage kick that crosses the line of scrimmage, and prior to the end of the kick, it is a foul if a kicking team player goes out of bounds voluntarily (without being contacted by a receiving team player) to [truncated]', 585, 107);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8878, 216, 8871, NULL, 2, 1, 'section', '2', '9.2', 'TOUCHING A SCRIMMAGE KICK', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8879, 216, 8878, NULL, 1, 2, 'article', '1', '9.2.1', 'TOUCHING BEHIND THE LINE', 'Any touching of the ball behind the line of scrimmage by a kicking team player is legal, even if the ball has crossed the line and returns behind the line.', 155, 30);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8880, 216, 8878, NULL, 2, 2, 'article', '2', '9.2.2', 'FIRST TOUCHING BEYOND THE LINE', '"First touching" is when a player of the kicking team touches a scrimmage kick in the field of play that is beyond the line of scrimmage before it has been touched by a player of the receiving team beyond the line. [truncated]', 1979, 366);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8881, 216, 8878, NULL, 3, 2, 'article', '3', '9.2.3', 'KICKING TEAM PLAYER OUT OF BOUNDS', 'A player of the kicking team, who has gone out of bounds during the kick, either of his own volition or by being legally forced out of bounds, may not touch or recover a scrimmage kick beyond the line of scrimmage until [truncated]', 761, 142);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8882, 216, 8878, NULL, 4, 2, 'article', '4', '9.2.4', 'BLOCKED INTO KICK', 'There is no distinction between a player touching a ball or being touched by it, but a player is not considered to have touched the ball if he is blocked into it by an opponent, provided he is in a passive position and [truncated]', 349, 67);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8883, 216, 8878, NULL, 5, 2, 'article', '5', '9.2.5', 'BALL BATTED OR ILLEGALLY KICKED INTO OPPONENT', 'A receiving team player is deemed to have not touched the ball if it is batted or illegally kicked into him by an opponent. [truncated]', 284, 53);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8884, 216, 8871, NULL, 3, 1, 'section', '3', '9.3', 'CATCH OR RECOVERY OF A SCRIMMAGE KICK', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8885, 216, 8884, NULL, 1, 2, 'article', '1', '9.3.1', 'KICKERS CATCH OR RECOVER BEHIND LINE', 'When a scrimmage kick is caught or recovered by the kicking team behind the line of scrimmage, the kicking team may advance, even if the ball has crossed the line and returned behind the line. [truncated]', 807, 149);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8886, 216, 8884, NULL, 2, 2, 'article', '2', '9.3.2', 'KICKERS CATCH OR RECOVER BEYOND LINE', 'When the kickers catch or recover a kick beyond the line of scrimmage, the ball is dead at the spot of recovery, even if a member of the receiving team has first touched the ball. [truncated]', 1393, 263);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8887, 216, 8884, NULL, 3, 2, 'article', '3', '9.3.3', 'RECEIVERS CATCH OR RECOVERY', 'If the receivers catch or recover any kick, they may advance. [truncated]', 165, 30);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8888, 216, 8884, NULL, 4, 2, 'article', '4', '9.3.4', 'SIMULTANEOUS CATCH OR RECOVERY', 'When a legal kick is simultaneously caught or recovered anywhere by two eligible opposing players, or if the ball is lying on the field of play with no player attempting to recover it, it is awarded to the receivers. [truncated]', 226, 40);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8889, 216, 8871, NULL, 4, 1, 'section', '4', '9.4', 'BALL CROSSES GOAL LINE, TOUCHES GOAL POSTS, OUT OF BOUNDS, DEAD IN FIELD OF PLAY', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8890, 216, 8889, NULL, 1, 2, 'article', '1', '9.4.1', 'BALL CROSSES RECEIVERS'' GOAL LINE', 'If a scrimmage kick crosses the receiver''s goal line from the impetus of the kick, the following shall apply: (a) If the ball has not been touched by a player of the receiving team beyond the line of scrimmage, it is [truncated]', 1446, 283);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8891, 216, 8889, NULL, 2, 2, 'article', '2', '9.4.2', 'KICK TOUCHES RECEIVERS'' GOAL POSTS', 'If a missed field goal or Try, or a punt, has touched the receiver''s goal post, uprights, or crossbar, the ball is dead in the receiver''s end zone, and all customary rules pertaining to punts, missed field goals, and [truncated]', 228, 41);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8892, 216, 8889, NULL, 3, 2, 'article', '3', '9.4.3', 'KICK TOUCHES KICKERS'' GOAL POSTS', 'If a scrimmage kick touches the kickers'' goal post, uprights, or crossbar, the ball is dead, and it is a safety. [truncated]', 124, 23);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8893, 216, 8889, NULL, 4, 2, 'article', '4', '9.4.4', 'BALL OUT OF BOUNDS OR NOT RECOVERED IN FIELD OF PLAY', 'If a scrimmage kick goes out of bounds between the goal lines or is lying in the field of play with no player attempting to recover it, it is the receiver''s ball at the dead ball spot, unless the special rules for [truncated]', 249, 48);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8894, 216, 8871, NULL, 5, 1, 'section', '5', '9.5', 'SPOTS OF ENFORCEMENT', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8895, 216, 8894, NULL, 1, 2, 'article', '1', '9.5.1', 'SPOTS OF ENFORCEMENT', 'If there is a foul from the time of the snap until a legal scrimmage kick ends, enforcement is from the previous spot. [truncated]', 2821, 508);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8896, 216, NULL, NULL, 10, 0, 'rule', '10', '10', 'OPPORTUNITY TO CATCH A KICK, FAIR CATCH', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8897, 216, 8896, NULL, 1, 1, 'section', '1', '10.1', 'OPPORTUNITY TO CATCH A KICK', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8898, 216, 8897, NULL, 1, 2, 'article', '1', '10.1.1', 'INTERFERENCE', 'During a scrimmage kick that crosses the line of scrimmage, or during a free kick, members of the kicking team are prohibited from interfering with any receiver making an attempt to catch the airborne kick, or from [truncated]', 1882, 351);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8899, 216, 8896, NULL, 2, 1, 'section', '2', '10.2', 'FAIR CATCH', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8900, 216, 8899, NULL, 1, 2, 'article', '1', '10.2.1', 'DEFINITION', 'A fair catch is an unhindered catch of a scrimmage kick that has crossed the line of scrimmage and has not touched the ground, or of a free kick that has not touched the ground, by a player of the receiving team who has [truncated]', 252, 50);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8901, 216, 8899, NULL, 2, 2, 'article', '2', '10.2.2', 'FAIR CATCH SIGNAL', 'Item 1. [truncated]', 2226, 419);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8902, 216, 8899, NULL, 3, 2, 'article', '3', '10.2.3', 'RESTRICTIONS', '(a) If a player of the receiving team makes a valid fair catch signal, and the ball is not touched by a player of the kicking team, the following apply: (1) If he catches the ball, it is dead immediately, and it is a [truncated]', 1256, 246);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8903, 216, 8899, NULL, 4, 2, 'article', '4', '10.2.4', 'PUTTING BALL IN PLAY AFTER FAIR CATCH', 'After a fair catch is made, or is awarded as the result of fair catch interference, the receiving team has the option of putting the ball in play by a: (a) fair catch kick (drop kick or placekick without a tee) from the [truncated]', 942, 171);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8904, 216, 8899, NULL, 5, 2, 'article', '5', '10.2.5', 'EXTENSION OF A PERIOD', 'If time expires during a play in which a player has signaled for a fair catch, the following shall apply: (a) If the player makes a fair catch, the receiving team may elect to extend the period with a fair catch kick, [truncated]', 547, 102);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8905, 216, NULL, NULL, 11, 0, 'rule', '11', '11', 'SCORING', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8906, 216, 8905, NULL, 1, 1, 'section', '1', '11.1', 'VALUE OF SCORES', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8907, 216, 8906, NULL, 1, 2, 'article', '1', '11.1.1', 'WINNING TEAM', 'The team that scores the greater number of points during the entire game is the winner. [truncated]', 290, 53);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8908, 216, 8906, NULL, 2, 2, 'article', '2', '11.1.2', 'TYPES OF SCORING PLAYS', 'Points are scored as follows: (a) Touchdown: 6 points (b) Field goal: 3 points (c) Safety: 2 points (d) Try after touchdown: 1 point (field goal or safety) or 2 points (touchdown)', 179, 32);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8909, 216, 8905, NULL, 2, 1, 'section', '2', '11.2', 'TOUCHDOWN', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8910, 216, 8909, NULL, 1, 2, 'article', '1', '11.2.1', 'TOUCHDOWN PLAYS', 'A touchdown is scored and the ball becomes dead when: (a) the ball is on, above, or behind the plane of the opponent''s goal line (extended) and is in possession of a runner who has advanced from the field of play into [truncated]', 832, 158);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8911, 216, 8905, NULL, 3, 1, 'section', '3', '11.3', 'TRY', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8912, 216, 8911, NULL, 1, 2, 'article', '1', '11.3.1', 'GENERAL RULES', 'After a touchdown, a Try is an opportunity for either team to score one or two additional points during one scrimmage down subject to 4-8-2-c and 16-1-3-a. [truncated]', 774, 149);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8913, 216, 8911, NULL, 2, 2, 'article', '2', '11.3.2', 'RESULTS OF A TRY', 'During a Try, the following shall apply: (a) If a kick results in a field goal by the offense, one point is awarded. [truncated]', 704, 135);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8914, 216, 8911, NULL, 3, 2, 'article', '3', '11.3.3', 'FOULS COMMITTED DURING TRY', 'If a foul results in a re-Try, Team A will have the option to enforce the penalty from the spot where it attempted the Try (previous spot) or from the yard line for the other Try option, the location of which is [truncated]', 3438, 644);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8915, 216, 8911, NULL, 4, 2, 'article', '4', '11.3.4', 'KICKOFF AFTER TRY', 'After a Try, the team on defense during the Try shall receive the kickoff (6-1-1-a).', 84, 15);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8916, 216, 8905, NULL, 4, 1, 'section', '4', '11.4', 'FIELD GOAL', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8917, 216, 8916, NULL, 1, 2, 'article', '1', '11.4.1', 'SUCCESSFUL FIELD GOAL', 'A field goal is scored when all of the following conditions are met: (a) The kick must be a placekick or dropkick made by the offense from on or behind the line of scrimmage or from the spot of a fair catch (fair catch [truncated]', 819, 153);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8918, 216, 8916, NULL, 2, 2, 'article', '2', '11.4.2', 'MISSED FIELD GOALS', 'If there is a missed field goal attempt that crosses the line of scrimmage, and the ball has not been touched by the receivers beyond the line of scrimmage in the field of play, or in the end zone before the ball has [truncated]', 2336, 452);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8919, 216, 8916, NULL, 3, 2, 'article', '3', '11.4.3', 'FAIR CATCH KICK', 'The rules for a field goal attempt from scrimmage apply to a field goal attempt following a fair catch (a fair catch kick). [truncated]', 600, 112);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8920, 216, 8916, NULL, 4, 2, 'article', '4', '11.4.4', 'NO TEE', 'An artificial or manufactured tee shall not be permitted to assist in the execution of a field goal.', 100, 18);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8921, 216, 8916, NULL, 5, 2, 'article', '5', '11.4.5', 'FOREIGN ARTICLES', 'No article of any type may be placed on the field, or used in any manner, to assist a player in the execution of a field goal and/or Try attempt. [truncated]', 245, 52);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8922, 216, 8916, NULL, 6, 2, 'article', '6', '11.4.6', 'BALL NEXT IN PLAY', 'After a field goal, the team scored upon will receive the kickoff. [truncated]', 79, 14);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8923, 216, 8905, NULL, 5, 1, 'section', '5', '11.5', 'SAFETY', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8924, 216, 8923, NULL, 1, 2, 'article', '1', '11.5.1', 'SAFETY', 'It is a safety: (a) when the offense commits a foul behind its own goal line and the defense elects to enforce the penalty at that spot. [truncated]', 2106, 405);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8925, 216, 8923, NULL, 2, 2, 'article', '2', '11.5.2', 'BALL IN PLAY AFTER SAFETY', 'After a safety, the team scored upon must put the ball in play by a free kick (punt, dropkick, or placekick) from its 20-yard line, unless an extension exception applies (4-8-2-g). [truncated]', 253, 43);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8926, 216, 8905, NULL, 6, 1, 'section', '6', '11.6', 'TOUCHBACK', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8927, 216, 8926, NULL, 1, 2, 'article', '1', '11.6.1', 'DEFINITION', 'It is a touchback if the ball is dead on or behind the goal line a team is defending, provided that the impetus comes from an opponent, and that it is not a touchdown or an incomplete forward pass. [truncated]', 343, 70);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8928, 216, 8926, NULL, 2, 2, 'article', '2', '11.6.2', 'TOUCHBACK SITUATIONS', 'When a team provides the impetus (3-17) that sends a loose ball behind its opponent''s goal line, it is a touchback: (a) if the ball is dead in the opponent''s possession in its end zone; (b) if the ball is out of bounds [truncated]', 1638, 304);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8929, 216, 8926, NULL, 3, 2, 'article', '3', '11.6.3', 'BALL NEXT IN PLAY', 'After a touchback, the team that has been awarded the touchback next snaps the ball at its 20-yard line from any point on or between the inbound lines, unless the touchback results from a free kick, in which case the [truncated]', 265, 49);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8930, 216, NULL, NULL, 12, 0, 'rule', '12', '12', 'PLAYER CONDUCT', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8931, 216, 8930, NULL, 1, 1, 'section', '1', '12.1', 'BLOCKING, USE OF HANDS AND ARMS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8932, 216, 8931, NULL, 1, 2, 'article', '1', '12.1.1', 'LEGAL AND ILLEGAL BLOCK', 'A player of either team may block (obstruct or impede) an opponent at any time, provided that the act is not: (a) pass interference (see Rule 8, Section 5, Article 1); (b) illegal contact (see Rule 8, Section 4); (c) [truncated]', 1475, 265);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8933, 216, 8931, NULL, 2, 2, 'article', '2', '12.1.2', 'LEGAL BLOCK BY OFFENSIVE PLAYER', 'An offensive player is permitted to block an opponent by contacting him with his head, shoulders, hands, and/or outer surface of the forearm, or with any other part of his body that is not prohibited by another rule. [truncated]', 1356, 247);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8934, 216, 8931, NULL, 3, 2, 'article', '3', '12.1.3', 'ILLEGAL BLOCK BY OFFENSIVE PLAYER', 'It is a foul if an offensive blocker: (a) Thrusts his hands forward above the frame of an opponent to forcibly contact him on the head or neck in a direct or prolonged manner; or Penalty: For illegal use of hands by the [truncated]', 2756, 500);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8935, 216, 8931, NULL, 4, 2, 'article', '4', '12.1.4', 'ASSISTING THE RUNNER AND INTERLOCKING INTERFERENCE', 'No offensive player may: (a) pull a runner in any direction at any time; (b) use interlocking interference, by grasping a teammate or by using his hands or arms to encircle the body of a teammate in an effort to block [truncated]', 491, 91);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8936, 216, 8931, NULL, 5, 2, 'article', '5', '12.1.5', 'LEGAL USE OF HANDS OR ARMS BY DEFENSE', 'A defensive player may use his hands, arms, or body to push, pull, or ward off offensive players: (a) when he is defending himself against an obstructing opponent while attempting to reach the runner; (b) when an [truncated]', 768, 133);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8937, 216, 8931, NULL, 6, 2, 'article', '6', '12.1.6', 'DEFENSIVE HOLDING', 'It is a foul for defensive holding if: (a) a defensive player tackles or holds any opponent other than a runner, except as permitted in Article 5. [truncated]', 627, 114);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8938, 216, 8931, NULL, 7, 2, 'article', '7', '12.1.7', 'ILLEGAL USE OF HANDS BY DEFENSE', 'It is a foul if a defensive player thrusts his hands or arms forward above the frame of an opponent to forcibly contact him on the head or neck in a direct or prolonged manner. [truncated]', 274, 53);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8939, 216, 8930, NULL, 2, 1, 'section', '2', '12.2', 'PERSONAL FOULS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8940, 216, 8939, NULL, 1, 2, 'article', '1', '12.2.1', 'CLIPPING', 'There shall be no clipping against a non-runner. [truncated]', 1410, 256);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8941, 216, 8939, NULL, 2, 2, 'article', '2', '12.2.2', 'PEEL BACK BLOCK', 'An offensive player cannot initiate contact on the side and below the waist against an opponent if: (a) the blocker is moving toward his own end line; and (b) he approaches the opponent from behind or from the side [truncated]', 350, 63);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8942, 216, 8939, NULL, 3, 2, 'article', '3', '12.2.3', 'ILLEGAL CUT BLOCK', 'See 8-4-5.', 10, 2);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8943, 216, 8939, NULL, 4, 2, 'article', '4', '12.2.4', 'BLOCKING BELOW THE WAIST', 'Blocks below the waist are prohibited in the following situations: (a) By players of either team after a change of possession; or (b) By players of the kicking team after a free kick, safety kick, fair catch kick, punt, [truncated]', 1084, 193);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8944, 216, 8939, NULL, 5, 2, 'article', '5', '12.2.5', 'CHOP BLOCK', 'All chop blocks are illegal. [truncated]', 1584, 277);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8945, 216, 8939, NULL, 6, 2, 'article', '6', '12.2.6', 'CRACKBACK BLOCK', 'Item 1. [truncated]', 1599, 280);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8946, 216, 8939, NULL, 7, 2, 'article', '7', '12.2.7', 'BLINDSIDE BLOCK', 'It is a foul if a player initiates a block when his path is toward or parallel to his own end line and makes forcible contact to his opponent with his helmet, forearm, or shoulder, unless the contact occurs in [truncated]', 709, 127);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8947, 216, 8939, NULL, 8, 2, 'article', '8', '12.2.8', 'UNNECESSARY ROUGHNESS', 'There shall be no unnecessary roughness. [truncated]', 2224, 390);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8948, 216, 8939, NULL, 9, 2, 'article', '9', '12.2.9', 'PLAYERS IN A DEFENSELESS POSTURE', 'It is a foul if a player initiates unnecessary contact against a player who is in a defenseless posture. [truncated]', 3586, 619);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8949, 216, 8939, NULL, 10, 2, 'article', '10', '12.2.10', 'IMPERMISSIBLE USE OF THE HELMET', 'It is a foul if a player: (a) lowers his head and makes forcible contact with his helmet against an opponent; or (b) uses any part of his helmet or facemask to butt or make forcible contact to an opponent''s head or neck [truncated]', 530, 99);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8950, 216, 8939, NULL, 11, 2, 'article', '11', '12.2.11', 'ROUGHING THE PASSER', 'Because the act of passing often puts the quarterback (or any other player attempting a pass) in a position where he is particularly vulnerable to injury, special rules against roughing the passer apply. [truncated]', 5728, 1012);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8951, 216, 8939, NULL, 12, 2, 'article', '12', '12.2.12', 'ROUGHING/RUNNING INTO THE KICKER', 'No defensive player may run into or rough a kicker who kicks from behind the line unless such contact: (a) is incidental to and occurs after the defender has touched the kick in flight, or occurs simultaneously with the [truncated]', 1687, 314);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8952, 216, 8939, NULL, 13, 2, 'article', '13', '12.2.13', 'ROUGHING THE HOLDER', 'It is a foul for roughing the holder if a defensive player forcibly contacts the holder of a place kick, unless the contact: (a) is incidental and occurs after the defender has touched the kick in flight; (b) is caused [truncated]', 1060, 189);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8953, 216, 8939, NULL, 14, 2, 'article', '14', '12.2.14', 'STRIKING, KICKING, TRIPPING OR KNEEING OPPONENTS', 'All players are prohibited from: (a) striking an opponent with his fists; (b) kicking or kneeing an opponent; (c) tripping an opponent, including the runner; (d) striking, swinging at, or clubbing the head or neck of an [truncated]', 1114, 202);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8954, 216, 8939, NULL, 15, 2, 'article', '15', '12.2.15', 'TWISTING, PULLING, OR TURNING THE FACEMASK OR HELMET OPENING', 'If a player grasps an opponent''s facemask or helmet opening, he must immediately release it. [truncated]', 451, 78);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8955, 216, 8939, NULL, 16, 2, 'article', '16', '12.2.16', 'HORSE-COLLAR TACKLE', 'No player shall grab the inside collar of the back or the side of the shoulder pads or jersey, or grab the jersey at the name plate or above, and pull the runner toward the ground. [truncated]', 471, 93);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8956, 216, 8939, NULL, 17, 2, 'article', '17', '12.2.17', 'USE OF HELMET AS A WEAPON', 'A player may not use a helmet that is no longer worn by anyone as a weapon to strike, swing at, or throw at an opponent. [truncated]', 286, 57);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8957, 216, 8939, NULL, 18, 2, 'article', '18', '12.2.18', 'OTHER PERSONAL FOULS', 'Fouls that include a 15-yard penalty, but are not listed in this Section or in Section 3, are considered Personal Fouls for penalty enforcement purposes.', 153, 25);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8958, 216, 8930, NULL, 3, 1, 'section', '3', '12.3', 'UNSPORTSMANLIKE CONDUCT', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8959, 216, 8958, NULL, 1, 2, 'article', '1', '12.3.1', 'PROHIBITED ACTS', 'There shall be no unsportsmanlike conduct. [truncated]', 6263, 1084);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8960, 216, 8958, NULL, 2, 2, 'article', '3', '12.3.3', 'INTENTIONAL FOULS TO MANIPULATE GAME CLOCK', 'A team may not commit multiple fouls during the same down in an attempt to manipulate the game clock. [truncated]', 321, 63);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8961, 216, 8958, NULL, 3, 2, 'article', '4', '12.3.4', 'PALPABLY UNFAIR ACT', 'A player or substitute shall not interfere with play by any act which is palpably unfair. [truncated]', 366, 58);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8962, 216, 8930, NULL, 4, 1, 'section', '4', '12.4', 'AUTOMATIC DISQUALIFICATION', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8963, 216, 8962, NULL, 1, 2, 'article', '1', '12.4.1', 'MULTIPLE UNSPORTSMANLIKE CONDUCT FOULS', 'In addition to any penalty referenced elsewhere in the Official Playing Rules, a player or non-player personnel will be automatically disqualified if that person is penalized twice in the same game for committing one of [truncated]', 1122, 181);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8964, 216, 8930, NULL, 5, 1, 'section', '5', '12.5', 'ILLEGAL BATS AND KICKS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8965, 216, 8964, NULL, 1, 2, 'article', '1', '12.5.1', 'ILLEGAL BAT', 'It is an illegal bat if: (a) any player bats or punches a loose ball in the field of play toward his opponent''s goal line; (b) any player bats or punches a loose ball (that has touched the ground) in any direction, if [truncated]', 622, 116);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8966, 216, 8964, NULL, 2, 2, 'article', '2', '12.5.2', 'ILLEGALLY KICKING BALL', 'No player may deliberately kick a loose ball or a ball that is in a player''s possession. [truncated]', 495, 93);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8967, 216, 8964, NULL, 3, 2, 'article', '3', '12.5.3', 'BALL BATTED OR ILLEGALLY KICKED INTO OPPONENT', 'A player is deemed to have not touched the ball if it is legally or illegally batted or illegally kicked into him by an opponent. [truncated]', 270, 50);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8968, 216, NULL, NULL, 13, 0, 'rule', '13', '13', 'NON-PLAYER CONDUCT', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8969, 216, 8968, NULL, 1, 1, 'section', '1', '13.1', 'NON-PLAYER CONDUCT', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8970, 216, 8969, NULL, 1, 2, 'article', '1', '13.1.1', 'NON-PLAYER FOULS', 'There shall be no unsportsmanlike conduct by a substitute, coach, attendant, or any other non-player (entitled to sit on a team''s bench) during any period or timeout (including between halves). [truncated]', 514, 86);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8971, 216, 8969, NULL, 2, 2, 'article', '2', '13.1.2', 'TEAM ATTENDANTS MAY ENTER FIELD DURING TIMEOUT', 'Either or both team attendants and their helpers may enter the field to attend to their team during a team timeout by either team. [truncated]', 690, 117);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8972, 216, 8969, NULL, 3, 2, 'article', '3', '13.1.3', 'BENCH CREDENTIALS', 'With the exception of uniformed players eligible to participate in the game, all persons in a team''s bench area must wear a visible credential clearly marked "BENCH." For all NFL games-pre-season, regular season, and [truncated]', 989, 159);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8973, 216, 8969, NULL, 4, 2, 'article', '4', '13.1.4', 'RESTRICTED AREAS', 'All team personnel must observe the zone restrictions applicable to the bench area and the border rimming the playing field. [truncated]', 577, 93);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8974, 216, 8969, NULL, 5, 2, 'article', '5', '13.1.5', 'MOVEMENT ON SIDELINES', 'Coaches and other non-participating team personnel (including uniformed players not in the game at the time) are prohibited from moving laterally along the sidelines any further than the points that are 18 yards from [truncated]', 623, 106);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8975, 216, 8969, NULL, 6, 2, 'article', '6', '13.1.6', 'NON-BENCH AREAS', 'Clubs are prohibited from allowing into the non-bench areas of field level any persons who have not been accredited to those locations by the home club''s public relations office for purposes related to news media [truncated]', 1014, 165);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8976, 216, 8969, NULL, 7, 2, 'article', '7', '13.1.7', 'PALPABLY UNFAIR ACT (NON-PLAYER)', 'A non-player shall not commit any act which is palpably unfair. [truncated]', 245, 37);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8977, 216, 8969, NULL, 8, 2, 'article', '8', '13.1.8', 'NON-PLAYER PERSONNEL', 'Non-player personnel of a club (e.g., management personnel, coaches, trainers, equipment personnel) are prohibited from making unnecessary physical contact with or directing abusive, threatening, or insulting language [truncated]', 764, 116);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8978, 216, NULL, NULL, 14, 0, 'rule', '14', '14', 'PENALTY ENFORCEMENT', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8979, 216, 8978, NULL, 1, 1, 'section', '1', '14.1', 'GENERAL RULES', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8980, 216, 8979, NULL, 1, 2, 'article', '1', '14.1.1', 'REFUSAL OF PENALTIES', 'Unless expressly prohibited, the penalty for any foul may be declined by the offended team, and play proceeds as though no foul had been committed. [truncated]', 403, 66);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8981, 216, 8979, NULL, 2, 2, 'article', '2', '14.1.2', 'NUMBER OF DOWN AFTER PENALTY', 'Item 1. [truncated]', 3005, 554);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8982, 216, 8979, NULL, 3, 2, 'article', '3', '14.1.3', 'CHOICE OF PENALTIES (MULTIPLE FOULS)', 'If there is a multiple foul (3-14-1-d) during the down, only one penalty may be enforced after the Referee has explained the alternatives to the offended team. [truncated]', 387, 69);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8983, 216, 8978, NULL, 2, 1, 'section', '2', '14.2', 'SPECIAL ENFORCEMENT FOR PENALTIES', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8984, 216, 8983, NULL, 1, 2, 'article', '1', '14.2.1', 'HALF-DISTANCE PENALTY', 'If the enforcement of a distance penalty would move the ball more than half the distance from the spot of enforcement to the offender''s goal line, the penalty shall be half the distance from the spot of enforcement to [truncated]', 463, 77);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8985, 216, 8983, NULL, 2, 2, 'article', '2', '14.2.2', 'FOUL BEHIND A GOAL LINE', '(a) When the spot of enforcement for a foul by the defense is behind the offensive goal line, a distance penalty is enforced from the goal line. [truncated]', 381, 72);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8986, 216, 8983, NULL, 3, 2, 'article', '4', '14.2.4', NULL, '(b), Note, for exception when a player''s momentum carries him into the end zone. [truncated]', 1248, 226);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8987, 216, 8978, NULL, 3, 1, 'section', '3', '14.3', 'SPOT FROM WHICH PENALTY IS ENFORCED', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8988, 216, 8987, NULL, 1, 2, 'article', '1', '14.3.1', 'GOVERNING PROVISIONS', 'The general provisions of Rule 14 govern all spots of enforcement, except for specific enforcements designated elsewhere in these rules.', 136, 20);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8989, 216, 8987, NULL, 2, 2, 'article', '2', '14.3.2', 'FOUL BY NON-PLAYER', 'Penalties for fouls committed by non-players shall be enforced as provided for in Rule 13.', 90, 15);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8990, 216, 8987, NULL, 3, 2, 'article', '3', '14.3.3', 'ENFORCEMENT SPOT NOT GOVERNED', 'When the spot of enforcement is not governed by a general or specific rule, it is the spot of the foul.', 103, 21);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8991, 216, 8987, NULL, 4, 2, 'article', '4', '14.3.4', 'SPOTS OF ENFORCEMENT', 'The spot of enforcement is the spot at which a penalty is enforced. [truncated]', 955, 186);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8992, 216, 8987, NULL, 5, 2, 'article', '5', '14.3.5', 'BASIC SPOT', 'The basic spot is a reference point that is used to determine the spot of enforcement for fouls committed pursuant to the Three-and-One Method of Enforcement. [truncated]', 666, 121);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8993, 216, 8987, NULL, 6, 2, 'article', '6', '14.3.6', 'THREE-AND-ONE METHOD OF ENFORCEMENT', 'For fouls committed during a run, a backward pass, or a fumble, the penalty is enforced from the basic spot if: (a) the defense fouls in advance of the basic spot; (b) the defense fouls behind the basic spot; or (c) the [truncated]', 1346, 242);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8994, 216, 8978, NULL, 4, 1, 'section', '4', '14.4', 'SPOTS OF ENFORCEMENT', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8995, 216, 8994, NULL, 1, 2, 'article', '1', '14.4.1', 'FOUL BEFORE OR AT THE SNAP', 'Item 1. [truncated]', 356, 68);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8996, 216, 8994, NULL, 2, 2, 'article', '2', '14.4.2', 'FOUL COMMITTED DURING RUNNING PLAY', 'For a foul committed during a running play when there is not a subsequent change of possession during the down, the basic spot is the dead ball spot. [truncated]', 376, 71);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8997, 216, 8994, NULL, 3, 2, 'article', '3', '14.4.3', 'FOUL COMMITTED DURING RUNNING PLAY BEFORE CHANGE OF POSSESSION', 'When a foul occurs during a running play, and the run in which the foul occurs is followed by a change of possession, the basic spot is the spot where possession is lost. [truncated]', 892, 154);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8998, 216, 8994, NULL, 4, 2, 'article', '4', '14.4.4', 'FOUL COMMITTED AFTER CHANGE OF POSSESSION (END ZONE ENFORCEMENT)', 'If there is a foul by either team after a change of possession, and the dead ball spot is in Team B''s end zone, enforcement shall be as follows: (a) Fouls by Team A: (1) If the impetus that sent the ball in touch was [truncated]', 1498, 297);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (8999, 216, 8994, NULL, 5, 2, 'article', '5', '14.4.5', 'FOUL COMMITTED DURING PASSING PLAY', 'If there is a foul by either team from the time of the snap until a forward pass thrown from behind the line ends, the penalty is enforced from the previous spot. [truncated]', 2547, 473);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9000, 216, 8994, NULL, 6, 2, 'article', '6', '14.4.6', 'FOUL DURING A BACKWARD PASS OR FUMBLE', 'If there is a foul by either team during a backward pass or fumble, the basic spot is the spot of the backward pass or fumble. [truncated]', 1269, 234);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9001, 216, 8994, NULL, 7, 2, 'article', '7', '14.4.7', 'FOUL DURING FREE KICK PLAY', 'If there is a foul during a free kick, enforcement is from the previous spot, and the free kick is made again. [truncated]', 1724, 324);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9002, 216, 8994, NULL, 8, 2, 'article', '8', '14.4.8', 'FOUL DURING SCRIMMAGE KICK PLAY', 'If there is a foul from the time of the snap until a legal scrimmage kick ends, enforcement is from the previous spot. [truncated]', 2811, 507);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9003, 216, 8994, NULL, 9, 2, 'article', '9', '14.4.9', 'DEAD BALL FOUL AND FOUL BETWEEN DOWNS', 'A dead ball foul is a foul that occurs in the continuing action after a down ends, or a taunting foul that occurs at any time. [truncated]', 3185, 578);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9004, 216, 8978, NULL, 5, 1, 'section', '5', '14.5', 'FOULS BY BOTH TEAMS (DOUBLE FOULS)', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9005, 216, 9004, NULL, 1, 2, 'article', '1', '14.5.1', 'DOUBLE FOUL WITHOUT CHANGE OF POSSESSION', 'If there is a double foul (3-14-1-e) during a down in which there is not a change of possession, the penalties are offset, and the down is replayed at the previous spot. [truncated]', 1662, 318);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9006, 216, 9004, NULL, 2, 2, 'article', '2', '14.5.2', 'DOUBLE FOUL WITH A CHANGE OF POSSESSION', 'If there is a double foul during a down in which there is a change or changes of possession, including if one of the fouls is a post-possession foul by Team B during a scrimmage kick, the team last gaining possession [truncated]', 1389, 259);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9007, 216, NULL, NULL, 15, 0, 'rule', '15', '15', 'INSTANT REPLAY', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9008, 216, 9007, NULL, 1, 1, 'section', '1', '15.1', 'INITIATING A REPLAY REVIEW', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9009, 216, 9008, NULL, 1, 2, 'article', '1', '15.1.1', 'COACH CHALLENGES', 'Each team is permitted two challenges that will initiate Instant Replay reviews: (a) The head coach can initiate a challenge by throwing a red flag onto the field of play before the next legal snap or kick. [truncated]', 1178, 207);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9010, 216, 9008, NULL, 2, 2, 'article', '2', '15.1.2', 'REPLAY OFFICIAL REQUEST FOR REVIEW', 'Only the Replay Official or the Senior Vice President of Officiating or his or her designee may initiate a review of a play: (a) that begins after the two-minute warning of each half; (b) throughout any overtime period; [truncated]', 1065, 187);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9011, 216, 9007, NULL, 2, 1, 'section', '2', '15.2', 'REPLAY REVIEWS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9012, 216, 9011, NULL, 1, 2, 'article', '1', '15.2.1', NULL, 'All Replay Reviews will be conducted by the Senior Vice President of Officiating or his or her designee. [truncated]', 433, 71);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9013, 216, 9011, NULL, 2, 2, 'article', '2', '15.2.2', 'LENGTH OF REVIEW', 'A decision must be made within 60 seconds from when video is shared with the Referee on the field.', 98, 19);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9014, 216, 9011, NULL, 3, 2, 'article', '3', '15.2.3', 'SCOPE OF REVIEW', 'Once a review is initiated, all reviewable aspects of a play (Section 3) may be examined and are subject to change, even if not the specific reason for the challenge.', 166, 30);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9015, 216, 9011, NULL, 4, 2, 'article', '4', '15.2.4', 'AWARDING POSSESSION', 'When the on-field ruling results in a dead ball (e.g., score, down by contact, incomplete pass, etc.), and following replay review it is determined that possession was lost before the ball should have been ruled dead, [truncated]', 580, 97);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9016, 216, 9011, NULL, 5, 2, 'article', '5', '15.2.5', 'EACH RULING REVIEWED SEPARATELY', 'Any aspect of a ruling that is not changed will be considered a correct ruling for purposes of reviewing the play.', 114, 21);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9017, 216, 9007, NULL, 3, 1, 'section', '3', '15.3', 'REVIEWABLE RULINGS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9018, 216, 9017, NULL, 1, 2, 'article', '1', '15.3.1', 'PLAY SITUATIONS', 'The Replay System will cover the following play situations: (a) Plays involving possession (see Section 3, Article 2). [truncated]', 805, 140);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9019, 216, 9017, NULL, 2, 2, 'article', '2', '15.3.2', 'PLAYS INVOLVING POSSESSION', 'Item 1. [truncated]', 2501, 461);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9020, 216, 9017, NULL, 3, 2, 'article', '3', '15.3.3', 'PLAYS INVOLVING TOUCHING OF EITHER THE BALL OR THE GROUND', 'Item 1. [truncated]', 1170, 215);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9021, 216, 9017, NULL, 4, 2, 'article', '4', '15.3.4', 'PLAYS GOVERNED BY THE GOAL LINE', 'Item 1. [truncated]', 1021, 195);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9022, 216, 9017, NULL, 5, 2, 'article', '5', '15.3.5', 'PLAYS GOVERNED BY THE BOUNDARY LINES', 'Item 1. [truncated]', 1455, 269);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9023, 216, 9017, NULL, 6, 2, 'article', '6', '15.3.6', 'PLAYS GOVERNED BY THE LINE OF SCRIMMAGE', 'Item 1. [truncated]', 377, 69);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9024, 216, 9017, NULL, 7, 2, 'article', '7', '15.3.7', 'PLAYS GOVERNED BY THE LINE TO GAIN', 'The dead ball spot is reviewable to determine whether it was short of, at, or beyond the line to gain. [truncated]', 590, 108);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9025, 216, 9017, NULL, 8, 2, 'article', '8', '15.3.8', 'NUMBER OF PLAYERS ON THE FIELD', 'Whether a player is on the field at the snap or when officials rule a dead ball foul for too many players in formation. [truncated]', 295, 63);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9026, 216, 9017, NULL, 9, 2, 'article', '9', '15.3.9', 'GAME ADMINISTRATION AND CONSULTATION', 'The Replay Official and designated members of the Officiating department may consult with on-field officials, or conduct a replay review, or advise the game officials on specific, objective aspects of a play when clear [truncated]', 2417, 429);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9027, 216, 9017, NULL, 10, 2, 'article', '10', '15.3.10', 'DISQUALIFICATION OF A PLAYER', 'The Senior Vice President of Officiating or his or her designee may review a decision by on-field officials to disqualify a player. [truncated]', 360, 59);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9028, 216, 9017, NULL, 11, 2, 'article', '11', '15.3.11', 'OTHER REVIEWABLE PLAYS', 'Item 1. [truncated]', 1255, 230);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9029, 216, 9007, NULL, 4, 1, 'section', '5', '15.5', 'GAME CLOCK ADMINISTRATION', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9030, 216, 9029, NULL, 1, 2, 'article', '1', '15.5.1', 'RESETTING GAME CLOCK', 'When a ruling is changed in replay, the clock status following review is determined by Rule 4-3, and the game clock will be reset to the time when the ball should have been declared dead. [truncated]', 264, 50);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9031, 216, 9029, NULL, 2, 2, 'article', '2', '15.5.2', '10-SECOND RUNOFF', 'When a changed ruling results in a running clock, or a clock that would have otherwise restarted before the next snap, for plays that begin after the two-minute warning, the clock is reset to the time when the play [truncated]', 666, 125);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9032, 216, 9007, NULL, 5, 1, 'section', '6', '15.6', 'TIMEOUTS FOLLOWING CHALLENGE', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9033, 216, 9032, NULL, 1, 2, 'article', '1', '15.6.1', 'UNSUCCESSFUL CHALLENGE', 'A team that makes an unsuccessful challenge is charged a team timeout. [truncated]', 262, 45);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9034, 216, 9032, NULL, 2, 2, 'article', '2', '15.6.2', 'CHARGED TIMEOUT', 'A charged timeout taken after the two-minute warning of either half with the clock running will be restored if a review changes the ruling and the new ruling results in a stopped clock. [truncated]', 311, 55);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9035, 216, 9007, NULL, 6, 1, 'section', '7', '15.7', 'FOULS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9036, 216, 9035, NULL, 1, 2, 'article', '1', '15.7.1', 'PENALTY ADMINISTRATION', 'Penalty administration, including the number of the down, yardage, the number of the fouling player, and the spot of a foul, is reviewable.', 139, 23);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9037, 216, 9035, NULL, 2, 2, 'article', '2', '15.7.2', 'FOUL NULLIFIED BY A CHANGED RULING', 'A foul will be nullified when a necessary aspect of the foul is changed in replay. [truncated]', 307, 58);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9038, 216, 9035, NULL, 3, 2, 'article', '3', '15.7.3', NULL, 'ENFORCEMENT OF FOULS FOLLOWING A CHANGED RULING Item 1. [truncated]', 796, 133);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9039, 216, NULL, NULL, 16, 0, 'rule', '16', '16', 'OVERTIME PROCEDURES', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9040, 216, 9039, NULL, 1, 1, 'section', '1', '16.1', 'OVERTIME PROCEDURES', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9041, 216, 9040, NULL, 1, 2, 'article', '1', '16.1.1', 'SCORE TIED', 'If the score is tied at the end of the regulation playing time of all regular season and postseason NFL games, a system of modified sudden-death overtime shall be in effect, pursuant to the following.', 200, 35);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9042, 216, 9040, NULL, 2, 2, 'article', '2', '16.1.2', 'END OF REGULATION', 'At the end of regulation playing time, the Referee shall immediately toss a coin at the center of the field, in accordance with rules pertaining to a usual pregame toss (4-2-2). [truncated]', 230, 41);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9043, 216, 9040, NULL, 3, 2, 'article', '3', '16.1.3', 'OVERTIME IN REGULAR SEASON', 'Following an intermission of no more than three minutes after the end of a regular game, an extra period of 10 minutes shall commence. [truncated]', 1261, 232);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9044, 216, 9040, NULL, 4, 2, 'article', '5', '16.1.5', NULL, '(a) below. [truncated]', 4949, 878);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9045, 216, NULL, NULL, 17, 0, 'rule', '17', '17', 'EMERGENCIES, UNFAIR ACTS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9046, 216, 9045, NULL, 1, 1, 'section', '1', '17.1', 'EMERGENCIES', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9047, 216, 9046, NULL, 1, 2, 'article', '1', '17.1.1', 'NON-PLAYER ON FIELD', 'If any non-player, including photographers, reporters, employees, police or spectators, enters the field of play or end zones, and in the judgment of an official said party or parties interfere with the play, the [truncated]', 338, 53);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9048, 216, 9046, NULL, 2, 2, 'article', '2', '17.1.2', 'FIELD CONTROL', 'If spectators enter the field and/or interfere with the progress of the game in such a manner that in the opinion of the Referee the game cannot continue, the Referee shall declare timeout. [truncated]', 712, 128);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9049, 216, 9046, NULL, 3, 2, 'article', '3', '17.1.3', 'GAME CALLED', 'If the game must be called due to a state or municipal law, or by darkness if no lights are available, an immediate report shall be made to the Commissioner by the home club, visiting club, and officials. [truncated]', 291, 53);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9050, 216, 9046, NULL, 4, 2, 'article', '4', '17.1.4', 'EMERGENCY SITUATIONS', 'The NFL affirms the position that in most circumstances all regular season and postseason games should be played to their conclusion. [truncated]', 964, 146);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9051, 216, 9046, NULL, 5, 2, 'article', '5', '17.1.5', 'LEAGUE AUTHORITY', 'The League employees vested with the authority to define emergencies under these procedures are the Commissioner, designated representatives from the League office staff, and the game Referee. [truncated]', 846, 125);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9052, 216, 9046, NULL, 6, 2, 'article', '6', '17.1.6', 'LATER DATE', 'If, because of an emergency, a regular season or postseason game is not started at its scheduled time and cannot be played at any later time that same day, the game nevertheless must be played on a subsequent date to be [truncated]', 251, 45);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9053, 216, 9046, NULL, 7, 2, 'article', '7', '17.1.7', 'PRE-GAME THREAT', 'If there is deemed to be a threat of an emergency that may occur during the playing of a game (e.g., an incoming tropical storm), the starting time of such game will not be moved to an earlier time unless there is [truncated]', 264, 50);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9054, 216, 9046, NULL, 8, 2, 'article', '8', '17.1.8', 'INTERRUPTED GAME', 'If, under emergency circumstances, an interrupted regular season or post season game cannot be completed on the same day, such game will be rescheduled by the Commissioner and resumed at that point.', 198, 32);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9055, 216, 9046, NULL, 9, 2, 'article', '9', '17.1.9', 'ALTERNATE DATES, SITES', 'In instances under these emergency procedures which require the Commissioner to reschedule a regular season game, the Commissioner will make every effort to set the game for no later than two days after its originally [truncated]', 598, 99);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9056, 216, 9046, NULL, 10, 2, 'article', '10', '17.1.10', 'POSTSEASON INTERRUPTION', 'If an emergency interrupts a postseason game and such game cannot be resumed on that same date, the Commissioner will make every effort to arrange for its completion as soon as possible. [truncated]', 487, 80);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9057, 216, 9046, NULL, 11, 2, 'article', '11', '17.1.11', 'GAME RESUMPTION', 'In all instances where a game is resumed after interruption, either on the same date or a subsequent date, the resumption will begin at the point at which the game was interrupted. [truncated]', 538, 91);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9058, 216, 9045, NULL, 2, 1, 'section', '2', '17.2', 'EXTRAORDINARILY UNFAIR ACTS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9059, 216, 9058, NULL, 1, 2, 'article', '1', '17.2.1', 'COMMISSIONER AUTHORITY', 'The Commissioner has the sole authority to investigate and take appropriate disciplinary and/or corrective measures if any club action, non-participant interference, or calamity occurs in an NFL game which the [truncated]', 386, 57);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9060, 216, 9058, NULL, 2, 2, 'article', '2', '17.2.2', 'NO CLUB PROTESTS', 'The authority and measures provided for in this entire Section 2 do not constitute a protest machinery for NFL clubs to avail themselves of in the event a dispute arises over the result of a game. [truncated]', 704, 116);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9061, 216, 9058, NULL, 3, 2, 'article', '3', '17.2.3', 'PENALTIES FOR UNFAIR ACTS', 'The Commissioner''s powers under this Section 2 include the imposition of monetary fines and draft-choice forfeitures, suspension of persons involved in unfair acts, and, if appropriate, the reversal of a game''s result [truncated]', 636, 98);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9062, 216, NULL, NULL, 18, 0, 'rule', '18', '18', 'GUIDELINES FOR CAPTAINS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9063, 216, 9062, NULL, 1, 1, 'section', '1', '18.1', 'GUIDELINES FOR CAPTAINS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9064, 216, 9063, NULL, 1, 2, 'article', '1', '18.1.1', 'NUMBER OF CAPTAINS', 'One hour and thirty minutes prior to kickoff: Respective coaches designate a maximum of six captains per team.', 110, 18);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9065, 216, 9063, NULL, 2, 2, 'article', '2', '18.1.2', NULL, 'COIN TOSS: (a) Up to six captains per team can participate in the coin toss ceremony (active, inactive, or honorary); only one captain from the visiting team (or a captain designated by the Referee if there is no home [truncated]', 434, 81);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9066, 216, 9063, NULL, 3, 2, 'article', '3', '18.1.3', NULL, 'CHOICE ON PENALTY OPTION: Only one captain is permitted to indicate the team''s penalty option.', 94, 15);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9067, 216, 9063, NULL, 4, 2, 'article', '4', '18.1.4', NULL, 'CHANGE OF CAPTAINS: (a) The coach has the prerogative of informing the Referee when he wishes to make a change in team captains. [truncated]', 539, 96);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9068, 216, NULL, NULL, 19, 0, 'rule', '19', '19', 'OFFICIALS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9069, 216, 9068, NULL, 1, 1, 'section', '1', '19.1', 'OFFICIALS', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9070, 216, 9069, NULL, 1, 2, 'article', '1', '19.1.1', 'GAME OFFICIALS', 'The game shall be played under the supervision of seven officials: the Referee, Umpire, Down Judge, Line Judge, Field Judge, Side Judge, and Back Judge. [truncated]', 264, 45);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9071, 216, 9069, NULL, 2, 2, 'article', '2', '19.1.2', 'JURISDICTION', 'The officials'' jurisdiction begins 100 minutes before the scheduled kickoff and ends when the Referee declares the final score.', 127, 19);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9072, 216, 9069, NULL, 3, 2, 'article', '3', '19.1.3', 'REFEREE''S AUTHORITY', 'The Referee is to have general oversight and control of the game. [truncated]', 440, 72);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (9073, 216, 9069, NULL, 4, 2, 'article', '4', '19.1.4', 'RESPONSIBILITIES AND MECHANICS', 'Officiating responsibilities and mechanics are specified in the Mechanics Manual, published annually by the National Football League.', 133, 17);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (62645, 216, NULL, NULL, 2, 0, 'rule', '2', '2', 'THE BALL', '', 0, 0);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (62646, 216, 62645, NULL, 1, 1, 'section', '1', '2.1', 'DIMENSIONS', 'The ball must be a "Wilson," hand selected, bearing the signature of the Commissioner of the League, Roger Goodell. [truncated]', 929, 164);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (62647, 216, 62645, NULL, 2, 1, 'section', '2', '2.2', 'SUPPLY', 'Each team will make 12 primary and 12 backup balls available for testing by the Referee no later than two hours and 15 minutes prior to the starting time of the game to meet League requirements. [truncated]', 1127, 202);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69236, 216, 8642, NULL, 4, 1, 'section', '4', '1.4', 'CHAIN CREW AND BALL CREW', 'Members of the chain crew and the ball crew must be uniformly identifiable as specified by the Commissioner. [truncated]', 166, 30);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69237, 216, 8642, NULL, 5, 1, 'section', '5', '1.5', 'SIDELINE MARKERS', 'The home club must provide and use the standard set of sideline markers that have been approved by the Commissioner.', 116, 20);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69238, 216, 8653, NULL, 14, 1, 'section', '1', '3.1', 'APPROVED RULING (A.R.)', 'An Approved Ruling (A.R.) is a written decision on a given statement of facts and serves to illustrate the intent and application of a rule. [truncated]', 728, 126);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69239, 216, 8653, NULL, 15, 1, 'section', '3', '3.3', 'BAT', 'A bat is the intentional striking of the ball with any part of the hand or arm. [truncated]', 91, 19);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69240, 216, 8653, NULL, 16, 1, 'section', '4', '3.4', 'BLOCKING', 'Blocking is the act of obstructing or impeding an opponent by contacting him with a part of the blocker''s body. [truncated]', 900, 177);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69241, 216, 8653, NULL, 17, 1, 'section', '5', '3.5', 'CHUCKING', 'Chucking is intentionally contacting an eligible receiver who is in front of a defender. [truncated]', 111, 17);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69242, 216, 8653, NULL, 18, 1, 'section', '6', '3.6', 'CLIPPING', 'Clipping is blocking an opponent from behind below the waist, provided the opponent is not a runner. [truncated]', 497, 85);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69243, 216, 8653, NULL, 19, 1, 'section', '7', '3.7', 'CLOSE-LINE PLAY', 'Close-line play is contact that occurs in an area extending between the outside edges of the normal tackle positions and three yards on either side of the line of scrimmage. [truncated]', 239, 41);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69244, 216, 8653, NULL, 20, 1, 'section', '8', '3.8', 'DISQUALIFIED PLAYER', 'A disqualified player is one who is prohibited from further participation in the game. [truncated]', 276, 49);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69245, 216, 8653, NULL, 21, 1, 'section', '11', '3.11', 'FIELD GOAL', 'A field goal is made by kicking the ball from the field of play through the plane of the opponent''s goal, which is an area either between the goal posts and above the cross bar, or, if above the goal posts, between the [truncated]', 435, 87);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69246, 216, 8653, NULL, 22, 1, 'section', '15', '3.15', 'HANDING THE BALL IS TRANSFERRING PLAYER POSSESSION FROM ONE TEAMMATE TO ANOTHER WITHOUT PASSING OR KICKING IT.', '(a) Except where permitted by rule, handing the ball forward to a teammate is illegal. [truncated]', 559, 98);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69247, 216, 8653, NULL, 23, 1, 'section', '16', '3.16', 'HUDDLE', 'A huddle is the action of two or more players in the field of play or in the end zone who, instead of assuming their normal position for the snap, free kick, or fair catch kick form a group for receiving instructions [truncated]', 259, 51);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69248, 216, 8653, NULL, 24, 1, 'section', '17', '3.17', 'IMPETUS', 'Impetus is the action of a player who carries the ball or provides the force (i.e., a pass, kick, snap, or fumble) that causes a ball in the field of play to touch or cross a goal line. [truncated]', 1286, 248);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69249, 216, 8653, NULL, 25, 1, 'section', '24', '3.24', 'PLAYER', 'A player is a participant of either team who is in the game.', 60, 13);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69250, 216, 8653, NULL, 26, 1, 'section', '26', '3.26', 'POCKET AREA', 'The pocket area is the area between the outside edges of the normal tackle positions on each side of the center extending backward to the offensive team''s end line. [truncated]', 231, 41);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69251, 216, 8653, NULL, 27, 1, 'section', '27', '3.27', 'POST-POSSESSION FOUL', 'A foul by the receiving team is a post-possession foul if it occurs during a scrimmage kick that crosses the line of scrimmage, provided that the receiving team does not lose possession during the rest of the down. [truncated]', 232, 41);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69252, 216, 8653, NULL, 28, 1, 'section', '28', '3.28', 'RUNNER', 'A runner is the offensive player who is in possession of a live ball (3-2-7), i.e., holding the ball or carrying it in any direction. [truncated]', 338, 62);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69253, 216, 8653, NULL, 29, 1, 'section', '29', '3.29', 'SAFETY', 'It is a safety, if the ball is dead in possession of a team on or behind its own goal line when the impetus (3-17) comes from the team defending that goal line. [truncated]', 290, 59);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69254, 216, 8653, NULL, 30, 1, 'section', '30', '3.30', 'SCRIMMAGE DOWN, FROM SCRIMMAGE, NOT FROM SCRIMMAGE', 'A scrimmage down is one that starts with a snap (3-32). [truncated]', 270, 50);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69255, 216, 8653, NULL, 31, 1, 'section', '31', '3.31', 'SHIFT', 'A shift is any simultaneous change of position or stance by two or more offensive players before the snap after the ball has been made ready for play for a scrimmage down, including movement to the line of scrimmage by [truncated]', 264, 48);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69256, 216, 8653, NULL, 32, 1, 'section', '32', '3.32', 'SNAP AND THE SNAPPER', 'A snap is a backward pass that puts the ball in play to start a scrimmage down, either by handing it or passing it backward from its position on the ground. [truncated]', 270, 50);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69257, 216, 8653, NULL, 33, 1, 'section', '33', '3.33', 'SUSPENDED PLAYER', 'A suspended player is one who must be withdrawn, in accordance with Rule 5, for correction of illegal equipment (5-4).', 118, 20);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69258, 216, 8653, NULL, 34, 1, 'section', '34', '3.34', 'TIGHT END BOX', 'The tight end box is a rectangle that is enclosed by imaginary lines two yards outside the normal tackle positions and five yards on either side of the line of scrimmage. [truncated]', 239, 44);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69259, 216, 8653, NULL, 35, 1, 'section', '35', '3.35', 'TACKLING', 'Tackling is an attempt by a defensive player to hold a runner to halt his advance or bring him to the ground.', 109, 22);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69260, 216, 8653, NULL, 36, 1, 'section', '39', '3.39', 'TOUCHDOWN', 'It is a touchdown if any part of the ball is on, above, or behind the opponent''s goal line while legally in possession of an inbounds player, provided it is not a touchback.', 173, 33);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69261, 216, 8653, NULL, 37, 1, 'section', '40', '3.40', 'TRIPPING', 'Tripping is the use of the leg or foot to obstruct any opponent (including a runner) (12-2-14).', 95, 17);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69262, 216, 8653, NULL, 38, 1, 'section', '41', '3.41', 'TRY', 'A Try is the attempt by a team that has scored a touchdown to add one point (by a field goal) or two points (by a touchdown) during one untimed scrimmage down (11-3).', 166, 33);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69263, 216, 8653, NULL, 39, 1, 'section', '42', '3.42', 'TWO-MINUTE WARNING', 'The two-minute warning is an automatic timeout that occurs at the conclusion of the last down for which the ball is legally snapped or kicked prior to two minutes remaining on the game clock in the second and fourth [truncated]', 224, 40);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69264, 216, 8653, NULL, 40, 1, 'section', '43', '3.43', 'T-FORMATION QUARTERBACK', 'A "T-Formation Quarterback" is defined as a player aligned one yard or less behind the snapper.', 95, 16);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69265, 216, 8730, NULL, 8, 1, 'section', '4', '4.4', 'STOPPING THE GAME CLOCK', 'The game clock operator shall stop the game clock (timeout) upon a signal by any official or upon the operator''s own positive knowledge: (a) at the end of a down in which there is a free kick or fair catch kick; (b) [truncated]', 768, 150);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69266, 216, 9007, NULL, 7, 1, 'section', '4', '15.4', 'THE FOLLOWING ASPECTS OF PLAYS ARE NOT REVIEWABLE:', '(a) Whether an erroneous whistle sounded; (b) Whether a ball was illegally batted or kicked; (c) Whether a passer intentionally grounded a pass; (d) Whether an ineligible receiver was downfield before a pass; (e) [truncated]', 422, 73);
INSERT INTO rule (rule_id, edition_id, parent_rule_id, lineage_id, ordinal, depth, unit_type, label, path_label, heading, body_text, char_count, token_count) VALUES (69267, 216, 9007, NULL, 8, 1, 'section', '8', '15.8', 'IF COMMUNICATIONS BETWEEN THE OFFICIALS AND THE LEAGUE OFFICE ARE LOST, THE REFEREE WILL STAY AT THE ON-FIELD MONITOR FOR ONE', 'minute while communications are being restored. [truncated]', 286, 43);
